quests[24604] = { id = 24604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Concern for Mankrik", description = "I would ask a favor of you, {class}.\n\nA warrior named Mankrik passed through our camp not long ago, on a lonely journey. His wife was killed by the quilboar, long ago, and he still seeks revenge. I cannot forget his eyes...burning with inconsolable hatred, every waking moment.\n\nWe did not talk long, but I cannot bear to think of him out there alone. Please, bring this to Mankrik, and tell him it is from me...", sourceObjective = "Bring Mahka's Gift to Mankrik, south of Firestone Point.", progress = "<Mankrik snarls.>\n\nWhat is it!? I'm busy!", completion = "Mahka sent you?\n\n<Mankrik's fury quells for a moment.>\n\nIt is a small comfort. But nothing can console me until I am done here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24606] = { id = 24606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Barrens", description = "This bright red stone, found clutched in the grasp of a quilboar, has been carefully carved into the likeness of a great boar, with thorny vines sprouting from its back. Its surface is smooth and worn with care.\n\nDid the quilboar make this? If you find others, maybe one of the shaman at Firestone Point could tell you more about them.", sourceObjective = "Collect 6 Blood Shard Trinkets from Razormane Quilboar.", progress = "Yes?", completion = "These are blood shards. They used to be found all over the Barrens.\n\nIt's said they were formed from the blood of Agamaggan, the great demigod that the quilboar sprang from. I knew the quilboar prized them, but nobody would think they'd take the time and care to carve them like this one...\n\nThere may be more to learn here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24607] = { id = 24607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Nortet to the east.", sourceObjective = "Meet with Nortet in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually look ta be in shape though. Steady hands. Fierce eyes. I may be able ta turn ya into a real {class}.\n\nLets not waste anymore time 'den.", sourceObjectiveStatus = "unverified-source-field" }
quests[24608] = { id = 24608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mangletooth", description = "I no longer care for honor or glory, {class}. All that matters to me is that the quilboar die, by any means, at anyone's hand.\n\nMangletooth, the chief of these filthy Razormane, sits in his lair to the northwest, atop a hill. End his life.\n\nI plan to stay here, and pile these bodies until no more vermin run squealing from the Kraul to face me...", sourceObjective = "Kill Mangletooth.", completion = "Good.  Good! They will all die!  Their chieftains, and their women, and their children, and their foul pets!", sourceObjectiveStatus = "unverified-source-field" }
quests[24609] = { id = 24609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for a Lord of Ironforge", description = "Did you want to make a Lovely Charm Bracelet for Muradin Bronzebeard? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Muradin Bronzebeard in Ironforge.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24610] = { id = 24610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the High Priestess of Elune", description = "Did you want to make a Lovely Charm Bracelet for the High Priestess of Elune? I'm sure she'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Tyrande Whisperwind in Darnassus.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24611] = { id = 24611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the Prophet", description = "Did you want to make a Lovely Charm Bracelet for the Prophet of the Exodar? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Prophet Velen in the Exodar.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24612] = { id = 24612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the Warchief", description = "Did you want to make a Lovely Charm Bracelet for the Warchief? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to the Warchief in Orgrimmar.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24613] = { id = 24613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the Banshee Queen", description = "Did you want to make a Lovely Charm Bracelet for the Banshee Queen? I'm sure she'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Lady Sylvanas Windrunner in Undercity.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24614] = { id = 24614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the High Chieftain", description = "Did you want to make a Lovely Charm Bracelet for the High Chieftain? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Baine Bloodhoof in Thunder Bluff.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24615] = { id = 24615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the Regent Lord of Quel'Thalas", description = "Did you want to make a Lovely Charm Bracelet for the Regent Lord of Quel'Thalas? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Lor'themar Theron in Silvermoon City.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24616] = { id = 24616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Losing Your Tail", description = "You must have many questions, {name}.  And they will be answered in time.\n\nI know why you're here and what you're looking for.\n\nI can't lead you there with the enemy tracking you.\n\nOne of Sylvanas's scouts has been following your tracks.  You can't lead the Forsaken to the place you seek.  Take this talisman and walk along the road just north of here.\n\nLet the ranger lure you to her trap and use the power of the talisman to break free and counterattack.", sourceObjective = "Use Belysra's Talisman to defeat the Dark Scout.", progress = "Is it done, {name}?", completion = "Well done, {name}.  The scout never had a chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[24617] = { id = 24617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal'doren, the Wild Home", description = "There are others like you, {name}.  And they too, were lost and confused.\n\nThere is a place where you belong.\n\nTal'doren, the wild home, was once home to an order of druids who took the shape of wolves.\n\nIt is there that you will find the answers you seek.  It is also there that you will find someone who can offer guidance.  An old friend.", sourceObjective = "Speak to Darius Crowley at Tal'doren, in the heart of the Blackwald.", completion = "You're all right, {name}!  I've been waiting for this day for a long time, it truly is great to see you friend.\n\nI've heard of what you've done and I'm thankful... especially for Lorna -- she's all I've left.  I will send for her right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[24618] = { id = 24618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claim the Battle Scar", description = "We have fought the Alliance to a standstill here, even as the land beneath our feet falls apart. To the east you will find the Battlescar, a wide swath of decimated terrain. It is little more than a line in the sand, but it must be OUR line.\n\nIn the center of the scar you will find a flag marker designating who controls it. Scout out the flag.\n\nIf it's not already ours, capture it for the Horde - it will swing the battle in our favor. Investigate the scar and kill anyone you find in there!", sourceObjective = "Go to the Battlescar. Scout out the flag marker and kill 10 Triumph Vanguard soldiers.\n\nCapturing the flag will give all Horde players in the scar a combat advantage.", completion = "Excellent! You're my kind of {class}, {name}.\n\nWith your help, we will throw these invaders back into the sea.", sourceObjectiveStatus = "unverified-source-field" }
quests[24619] = { id = 24619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parts-is-Parts", description = "I've always wanted to try making an abomination. It looks simple enough, but you know how it is when you learn things from a book. There's no substitute for doing!\n\nFirst, I'm going to need parts. Lots of parts. And you're going to get them for me.\n\nNo need to be picky: human, orc... it doesn't matter. Parts is parts.\n\nJust be sure the corpses you harvest come from the Battlescar, so I know they're fresh.\n\n<Calder presses a rusted, gore-covered bonesaw into your hands and smiles disarmingly.>", sourceObjective = "Use Calder's Bonesaw on corpses within the Battlescar and collect 15 Severed Extremities.", progress = "Did you get my parts? Let me see them!", completion = "<Calder peers into the sack of extremities and licks his lips with a dry, black tongue.>\n\nOh my. This is exciting.\n\n Aren't you excited, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24620] = { id = 24620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hearts-is-Hearts", description = "These parts - so lovely! Muscle and sinew and fingers and toes ... I am SO hungry right now.\n\nBut work must come first. Once I stitch this pile of parts together I'm going to need a heart strong enough to pump sludge through this rat's nest of veins. I would use my own heart, but it's a shriveled up husk resembling a turnip.\n\nNo, I need some real power. Get me a kodo heart from one of those giant landquaker bulls to the south of the Battlescar.", sourceObjective = "Slay a Landquaker Bull south of the Battlescar and collect an Enormous Kodo Heart.", progress = "You've gotta have heart, {name}. All you really need is heart.", completion = "<Calder grasps the gigantic heart in both hands, squeezing it and listening to the valves slurp and squish.>\n\n<His pale mask of a face splits open into an enormous, childlike grin.>\n\nIt is so very important to love one's work, wouldn't you agree, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24621] = { id = 24621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smarts-is-Smarts", description = "My monstrosity is taking shape! All that's left is to stuff his skull with something useful.\n\nI'm talking about brains, {name}. And here I'm going to be picky. The abomification process causes significant brain damage so it's best to start with someone smart.\n\nOne of the Alliance officers should do nicely. Seek out one of the Captains on the far side of the Battlescar and try not to damage the goods while you kill him.", sourceObjective = "Kill a Triumph Captain on the far side of the Battlescar and acquire a Fresh Brain.", progress = "Brraaaaaaiiinnnnss...", completion = "<Calder holds the brains in an outstretched hand while withdrawing a gore-caked multi-tool from his belt.>\n\nWonderful work! Now the secret here is to leave the reptilian nervous systems intact while removing the higher cognitive functions. We can't have our new friend developing a conscience or remembering he's Alliance...\n\n<Calder digs and snips at the brain, removing large chunks.>\n\nAnd... we're finished! How lovely.", sourceObjectiveStatus = "unverified-source-field" }
quests[24622] = { id = 24622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Troll's Truest Companion", description = "If ya lookin' for something ta do, we need some more raptors moved over to da pens. If ya head over to da island south of here, you can be meetin' with our caretakers and dey can set ya up.\n\nDey might appreciate a hand too. Got ta be spreadin' da love, ya know?", sourceObjective = "Speak to Kijara on Bloodtalon Shore.", completion = "Nice ta see new faces 'round here, mon. It's easy ta get ta feelin' isolated since we left Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24623] = { id = 24623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Young", description = "I actually have somethin' really important dat I could use help with, if ya be willin', mon.\n\nOur hatchlins' are bein' stolen by someone on da next island. At first I thought dey were just runnin' away or that nature be claimin' dem, but we are missin' more than a dozen of da little guys now.\n\nPlease head to Zalazane's Fall to da northwest and point da little hatchlins back dis way. Poor tings.", sourceObjective = "Use the Bloodtalon Whistle to rescue 12 Lost Bloodtalon Hatchlings.", completion = "Thank ya so much! They can be vicious when provoked, but most of da time dey don't know betta.", sourceObjectiveStatus = "unverified-source-field" }
quests[24624] = { id = 24624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mercy for the Lost", description = "The fiend who stole our raptors has been corruptin' dem with some kind of magic. Now dat dey've grown with dis corruption inside of them, I fear dere's little we can be doin' to save dem outside grantin' them da peace of death. Go ta Zalazane's Fall, northwest of here, an' see da task done.\n\nI hope ya can stomach dae work. I don't tink I could bring myself ta do da deed, even knowin' that it be needed.", sourceObjective = "Kill 8 Corrupted Bloodtalon Raptors.", completion = "Thank you, {class}.\n\nIt will be takin' brave and determined people like you ta drive da Darkspear up again. I hope dere are more people even half as dedicated to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[24625] = { id = 24625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consort of the Sea Witch", description = "I been investigatin' our corrupted Bloodtalons troubles and I think I've found da source. A lone naga. He was holdin' a red orb aloft over our hatchlings and I could see dem... changin'.\n\nI'm certain he tinks his thievery and spellcastin' have gone unnoticed, so ya should be able ta catch him unawares. Kill dis naga and bring me back dat vile orb - you'll be findin' him to da northwest, at Zalazane's Fall.", sourceObjective = "Kill Naj'tess and retrieve his orb.", progress = "Da naga have been our enemies for a long, long time, and our previous encounters with dem have not gone well. It be clear dat dis time will be different. Tings have changed, and you be part of dat change.", completion = "Well done, {name}! Dis naga has set us back quite some time, but nothin' will be holdin' us down foreva.\n\nIt's good ta be havin' ya wit us, {name}. Ya have a fierce heart within ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24626] = { id = 24626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Young and Vicious", description = "Ya be a good one, {name}.\n\nMoraya was askin' for new raptors ta train. We shouldn't keep her waitin' any longa! I have a few other recruits bringin' some over as well, but I have a special one dat I've been promisin' Moraya for a while.\n\nSwiftclaw be one of our fastest and bravest young raptors yet, but he can be a bit unruly. I'll lend ya da lasso, I just need ya to catch him somewhere on da island here and steer him over to da pens on da main isle. I doubt he'll be makin' it easy on ya though.", sourceObjective = "Capture Swiftclaw and bring him back to the pens near Darkspear Hold.", completion = "Swiftclaw! Kijara was tellin' me about him and he sounded like he'd be a handful. I don't mind da challenge - it's da spirited ones like dat that be makin' da bravest and truest companions when real times of need be comin'.\n\nTank ya, hon. Ya've been very helpful.", sourceObjectiveStatus = "unverified-source-field" }
quests[24627] = { id = 24627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At Our Doorstep", description = "The night elves have taught us much during this time, {name}.  They've taught us who we are and where we come from.\n\nThanks to them... thanks to this place... we're no longer mere beasts.  We have regained free will.\n\nThe Forsaken aren't here for our land alone.\n\nThey're looking for something we possess.  An artifact capable of uncontrollably spreading the Curse to all humanity.  We cannot let them find it.\n\nSylvanas's banshees have come very close.  Help my trackers take them out.", sourceObjective = "Kill 6 Howling Banshees.", progress = "You're back, {name}.", completion = "You are as good as I remember, {name}.  It is good to have you back.", sourceObjectiveStatus = "unverified-source-field" }
quests[24628] = { id = 24628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations", description = "What you know as the Curse began as a heresy among our brethren.\n\nFaced with a losing battle against demonic forces, the Druids of the Pack eschewed the balance they were sworn to and allowed the beast to overtake them.\n\nThey were banished to the Emerald Dream where they live in eternal slumber under a tree identical to this one, but not before their curse spread to others.\n\nToday our ceremony will restore balance to your people. Bring me the leaf that grows only in Tal'doren's vicinity.", sourceObjective = "Bring 6 Moonleafs to Vassandra.", progress = "You've returned, {name}.", completion = "These simple leaves grow by Elune's grace.  They will help your mind understand the need for balance and your soul will permanently earn mastery over the beast.", sourceObjectiveStatus = "unverified-source-field" }
quests[24629] = { id = 24629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Puff of Perfume", description = "You look like a real go-getter, {class}. How about we work out a little win-win scenario?\n\nCrown's looking to offer samples of our latest holiday-themed products to as many potential customers as possible. Help us share the love, and we'll give you discounts on some great Crown merchandise!\n\nYour time, our money, friend. What do you say?", sourceObjective = "Spray 10 people with the Crown Perfume Sprayer.", completion = "Great work, {name}! People will come running to buy Crown perfumes now that they've had a chance to sample their wonders.\n\nHere's a little something for helping us out.", sourceObjectiveStatus = "unverified-source-field" }
quests[24631] = { id = 24631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flightmare", description = "The Alliance has hired in Wildhammer mercenaries to control the skies over the Battlescar. I believe these same gryphon-riders were the ones to firebomb Taurajo during the attack.\n\nI want our skies scoured clean.\n\nThe wildhammer dwarves fly low enough for a sharp-eyed {class} to hook them. Take this. Target their gryphons and dismount the riders - once grounded, show them no mercy.", sourceObjective = "Use Tomusa's Hook on Triumph War Gryphons to dismount and kill 5 Wildhammer Mercenaries.", progress = "The Wildhammer are fierce fighters, in the air or on the ground. How goes the battle?", completion = "<Tomusa snorts as he takes back his hook.>\n\nVengeance feels hollow. Still. I could not allow them to go unpunished.", sourceObjectiveStatus = "unverified-source-field" }
quests[24632] = { id = 24632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tauren Vengeance", description = "My people are not wrathful by nature, but sometimes a thirst for justice causes us to take up arms in anger.\n\nMy old friend Gann Stonespire, on learning of the butchery in Taurajo, flew into a fury. Tribal elders could no longer hold his rage in check.\n\nNow he has all but parted ways with the Horde. He's gone rogue, {name}, and seeks to lash out at the Alliance with a small band of like-minded partisans.\n\nIf you, too, seek vengeance, you will find him southeast of here, at the foot of Bael Modan.", sourceObjective = "Seek out Gann Stonespire at Spearhead in Southern Barrens.", completion = "<Gann looks you up and down.>\n\nWe could use your help, {class}. But this is not a skirmish. We fight here to strike a killing blow... or die trying.", sourceObjectiveStatus = "unverified-source-field" }
quests[24633] = { id = 24633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mahka's Plea", description = "I can't put him out of my mind, {name}. Sometimes at night, I can hear his howls of rage and suffering, echoing across the plains. To imagine him out there, alone and in such pain...\n\nPlease, I must ask a favor of you. Go to Mankrik, and tell him to come see me.", sourceObjective = "Talk to Mankrik.", progress = "I am sorry to ask this of you, but I want him to come here. He needs to leave that place of death...", completion = "Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24634] = { id = 24634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intelligence Warfare", description = "I am convinced the Alliance is using spies to scout the field and pass along information. They knew to strike at Taurajo while the hunters were afield. And they countered every one of Gar'dul's moves like he was an open book.\n\nWell {name}, I for one will not be outplayed. Not here. We will win the battle for intelligence.\n\nEven now I hear reports of Alliance operatives slinking around in the shadows, especially here, outside these very walls. Kill them and bring me back something of use.", sourceObjective = "Kill a Barrens Operative and retrieve the SI:7 Briefings.", progress = "Watch your back, {class}. They could be anywhere.", completion = "Hah! The fool didn't destroy these orders.\n\nLet's see what we can learn...", sourceObjectiveStatus = "unverified-source-field" }
quests[24635] = { id = 24635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cloudlet of Classy Cologne", description = "You seem the enterprising sort, {class}. How about we make a little deal?\n\nCrown wants to offer samples of our latest holiday-themed products to as many potential customers as we can. Help us share the love while earning some fantastic Crown merchandise!\n\nYour time, our money, friend. What do you think?", sourceObjective = "Spray 10 people with the Crown Cologne Sprayer.", progress = "That cologne isn't going to give itself out, you know.\n\nGet spraying!", completion = "Nice work, {name}! People will be buying Crown colognes by the crate-load now that they've had a chance to try them.\n\nHere's a little something for helping us out.", sourceObjectiveStatus = "unverified-source-field" }
quests[24636] = { id = 24636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonbon Blitz", description = "I can see you've got an eye for opportunity, {class}. What do you say we make a little coin together?\n\nCrown needs to push samples of our latest holiday-themed products to every potential customer in the city. Help us share the love, and we'll share some of that amazing Crown merchandise with you!\n\nYour time, our money, friend. We got a deal?", sourceObjective = "Toss 10 people samples from the Crown Chocolate Sampler.", progress = "You know, those chocolates aren't going to fling themselves at people.\n\nYou need to get to work!", completion = "Lovely work, {name}! People will be tripping over one another to get Crown chocolates now that they've had a chance to taste those sweet, romantic treats.\n\nHere's a little something for helping us out.", sourceObjectiveStatus = "unverified-source-field" }
quests[24637] = { id = 24637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Butcher of Taurajo", description = "This operative had orders to secure the roadways between the Alliance command and Fort Triumph. General Hawthorne is on the move.\n\n<Bloodhilt crumples the documents in his fist.>\n\nIt's HIM, {name}! Hawthorne - I spit the name - he is the one who ordered the assault on Taurajo! Now we know when and where to strike him down. Quickly, follow the road north of the Battlescar and meet up with my assassin Karthog. CRUSH Hawthorne and string his body up along the road!", sourceObjective = "Speak with Karthog, then lure out and assassinate General Hawthorne.", completion = "<Upon hearing the news, Bloodhilt snorts. His eyes gleam. He tips his head back and bellows a wet, cackling laugher that echoes between the blackened walls of Desolation hold and reverberates throughout the hills beyond.>\n\nSo it is done! The Butcher of Taurajo is felled at last. Cut down in the streets like a dog. Fitting.\n\nYou have done well, {name}. You've sowed fear into our enemies, and soon we will reap the harvest!", sourceObjectiveStatus = "unverified-source-field" }
quests[24638] = { id = 24638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's right outside Orgrimmar's gates, to the west! That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Lackeys and use Snagglebolt's Khorium Bomb to damage one Chemical Wagon just west of Orgrimmar's gates in Durotar, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24639] = { id = 24639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start with da basics. I need ta know dat you know how ta swing dat weapon you're totin' around.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", sourceObjective = "Destroy 6 Tiki Targets.", completion = "Not bad, mon. Ya have a natural flow to ya swings - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", sourceObjectiveStatus = "unverified-source-field" }
quests[24640] = { id = 24640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Warrior", description = "I tink I have something I can show ya. It's pretty simple really, but it should help.\n\nWhen ya want ta close tha distance with an enemy quickly, ya can charge dem with a fierce roar. Dis will take them off guard, stunnin' them and opening up an opportunity ta follow up with attacks before dey can defend demselves.\n\nTry it out. Let me know when ya tink you have it down.", sourceObjective = "Speak to Nortet to train Charge. Practice using Charge against a Tiki Target.", progress = "Veteran warriors can control much of da battlefield simply with da strength of deir presence. Whether it be rallyin' other fighters beside ya to greater strength, demoralizin' ya enemies with da fierceness of ya attacks, our intimidatin' ya foes into runnin' from da very sight of ya, it's more than just the weapon dat makes da {class}.", completion = "Good work, mon! Dis stuff come easy to ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24641] = { id = 24641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", sourceObjective = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", sourceObjectiveStatus = "unverified-source-field" }
quests[24642] = { id = 24642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", sourceObjective = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day.", sourceObjectiveStatus = "unverified-source-field" }
quests[24643] = { id = 24643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", sourceObjective = "Report to Vol'jin at Darkspear Hold.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear.", sourceObjectiveStatus = "unverified-source-field" }
quests[24645] = { id = 24645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just outside Ambermill in Silverpine Forest. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Thugs and use Snagglebolt's Khorium Bomb to destroy one chemical wagon outside of Ambermill in Silverpine Forest, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24646] = { id = 24646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Back What's Ours", description = "Ever since the Forsaken invaded Gilneas, we've tried to keep the location of the Scythe of Elune secret.   We moved it at night to one of many safe locations.  The Dark Rangers got close, but never found it... until now.\n\nThey were last spotted at the Woods' End Cabin, west of here.  Blow this horn when you find them and Tobias and his trackers will engage the Dark Rangers.\n\nOnly then will it be safe for you to venture inside the cabin and take back the scythe.  Hurry, {name}.  It must not reach Sylvanas.", sourceObjective = "Blow the Horn of Tal'doren at the Woods' End Cabin and retrieve the Mysterious Artifact inside.", progress = "Do you have the scythe, {name}?", completion = "I knew we could count on you.  You've done well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24647] = { id = 24647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just outside the village of Hillsbrad in -- you guessed it -- Hillsbrad Foothills. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Dusters and use Snagglebolt's Khorium Bomb to destroy one chemical wagon just outside of Hillsbrad Village in Hillsbrad Foothills, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24648] = { id = 24648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's near Sentry Point, just outside Theramore in Dustwallow. Don't give me that look, okay? This is a problem for us, too. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Hoodlums and use Snagglebolt's Khorium Bomb to destroy one chemical wagon outside of Theramore in Dustwallow Marsh, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24649] = { id = 24649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's to the east of Aerie Peak in the Hinterlands. Don't give me that look, okay? This is a problem for the Horde, too. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Agents and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Aerie Peak in the Hinterlands, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24650] = { id = 24650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's in Winterspring, just east of Everlook. Oh, now this is personal. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Sprinklers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Everlook in Winterspring, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24651] = { id = 24651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's just east of Shattrath, in Terokkar Forest. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Underlings and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Shattrath City in Terokkar Forest, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24652] = { id = 24652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's in the Forlorn Woods of Crystalsong, northwest of the Mirror of Twilight. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Sprayers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon in the Forlorn Woods of Crystalsong Forest, then return to Detective Snap Snagglebolt in Orgrimmar.", progress = "Did you teach 'em a lesson?", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24653] = { id = 24653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Agamaggan", description = "I think the quilboar are being driven by more than just crude desire. Would you help me look into this further?\n\nTo the west, scattered among the quilboar's settlements and camps, I've noticed boar skulls. They gleam from a distance, polished smooth...distinct from the remains littered in their waste piles. I think these may be objects of worship.\n\nBring me several of these to examine, {name}.", sourceObjective = "Collect 3 Polished Boar Skulls.", progress = "Do you have the skulls?", completion = "Yes, these are clearly symbols of Agamaggan. But if the quilboar are still devoted to their dead god, what is the source of their vicious agression?  It is said Agamaggan was noble, and even gave his life fighting the Burning Legion...\n\nA moment, {name}. We must confer with the spirits.", sourceObjectiveStatus = "unverified-source-field" }
quests[24654] = { id = 24654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silithissues", description = "The silithid! They're bugs, {name}. Or something like bugs. They're not natural... and we built a fortress on the equivalent of an anthill.\n\nTake this burning pitch. It'll set the buggers on fire and plug up their burrows at the same time. Be careful when you pour this stuff on there - the silithid will come out in swarms!\n\nLook for silithid mounds around the exterior of Desolation Hold. They look like heaps of sand. Kill anything that crawls out.", sourceObjective = "Use the Bucket of Burning Pitch on Silithid Mounds and kill 10 Silithid Swarmers as they emerge.", progress = "The Alliance is nothing. Swarms of those critter-crawlys?\n\n<Crawgol shudders.>", completion = "You're covered in hot tar and bug juice! Don't worry, friend. It'll come off.\n\nSomeday.", sourceObjectiveStatus = "unverified-source-field" }
quests[24655] = { id = 24655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Stinks", description = "Get a load of these guys, would ya? Steamwheedle's been handling the business of holidays for years, and all of a sudden, these guys bust into the market. They're not Steamwheedle; the cartel hired me to get to the bottom of this. Something stinks here and it ain't just perfume.\n\nTake this device I brought and go analyze the perfume clouds around the guards. I want to know what they're putting in that stuff. Things ain't natural.", sourceObjective = "Use Snagglebolt's Air Analyzer to test the air around 6 heavily perfumed guards, then return to Inspector Snip Snagglebolt in Stormwind.", progress = "You analyze that reek yet, kid?", completion = "Hey, thanks, kid. Give it over, let's take a look.\n\n<He takes the device from you and fiddles with it.>\n\nOh, that ain't good.", sourceObjectiveStatus = "unverified-source-field" }
quests[24656] = { id = 24656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilfering Perfume", description = "I knew they were up to no good! There's some sort of mind-affecting chemical in here, but I can't get a handle on it with such a small sample. I need the real stuff.\n\nDon't just go over there and buy it! I don't want you giving these scumbags one copper. Nah, you gotta get it from the source, discreet-like.\n\nI'll disguise you as a package runner. I saw a stockpile guarded by their goons outside the gates. Go run by, and DON'T stop, or they'll make you! They'll toss you a crate. Bring it back here.", sourceObjective = "While disguised as a package-runner, go to the Crown Chemical Company's stockpile outside the gates of Stormwind, then return the package they toss you to Inspector Snip Snagglebolt in Stormwind.", progress = "Did they toss ya a crate to deliver?", completion = "You got it, huh? Good job, kid. Top notch. Let's see what we got here.\n\n<He cracks open the crate and rummages around inside.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24657] = { id = 24657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friendly Chat...", description = "<Marion listens with horror as you tell her why you're trying to track down Snivel.>\n\nYou mean, he might've used some kind of chemical on me? Ew! I can't believe I fell for that fraud!\n\nIf he's finished all of his errands, he's on his way down to the docks to catch a ship to the South Seas! Whatever you do, {name}, you can't let him get away with this.\n\nHurry down to Stormwind Harbor before you miss him!", sourceObjective = "Go to Stormwind Harbor and question Snivel Rustrocket about the supplies. Return with any evidence he gives you.", progress = "Did you find the guy, or did he crawl under a rock?", completion = "You got his ledger? Really? That's great, {name}. There's probably loads of good information in here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24658] = { id = 24658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's northeast of Westbrook Garrison right outside in Elwynn! That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Lackeys and use Snagglebolt's Khorium Bomb to damage one Chemical Wagon northeast of Westbrook Garrison in Elwynn Forest, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24659] = { id = 24659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just south of the Grove of the Ancients in Darkshore. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Thugs and use Snagglebolt's Khorium Bomb to destroy one chemical wagon south of the Grove of the Ancients in Darkshore, then return to Inspector Snip Snagglebolt in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[24660] = { id = 24660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just southeast of Darkshire in Duskwood. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Dusters and use Snagglebolt's Khorium Bomb to destroy one chemical wagon at the abandoned farm southeast of Darkshire in Duskwood, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24661] = { id = 24661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's right outside Orgrimmar's gates, to the west! That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Lackeys and use Snagglebolt's Khorium Bomb to damage one Chemical Wagon just west of Orgrimmar's gates in Durotar, then return to Detective Snap Snagglebolt in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24662] = { id = 24662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's near Sentry Point, just outside Theramore in Dustwallow. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Hoodlums and use Snagglebolt's Khorium Bomb to destroy one chemical wagon outside of Theramore in Dustwallow Marsh, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24663] = { id = 24663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's to the east of Aerie Peak in the Hinterlands. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Agents and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Aerie Peak in the Hinterlands, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24664] = { id = 24664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's in Winterspring, just east of Everlook. Oh, now this is personal. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Sprinklers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Everlook in Winterspring, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24665] = { id = 24665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's just east of Shattrath, in Terokkar Forest. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Underlings and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Shattrath City in Terokkar Forest, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24666] = { id = 24666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's in the Forlorn Woods of Crystalsong, northwest of the Mirror of Twilight. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Sprayers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon in the Forlorn Woods of Crystalsong Forest, then return to Inspector Snip Snagglebolt in Stormwind.", progress = "Did you teach 'em a lesson?", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24667] = { id = 24667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firestone Point", description = "I've been on top of this silithid situation for almost a month, which makes me the local expert. Just last week the Earthen Ring was visiting, and wanted me to write down everything I know.\n\n<Crawgol hands you a tattered book.>\n\nI'm not much of a writer. Or a reader, for that matter. But this book is probably the most definitive thing ever written about this foe.\n\nDeliver it to Tauna Skychaser down in Firestone Point. It's south of here, just west of the main road.", sourceObjective = "Deliver Crawgol's Silithid Field Guide to Tauna Skychaser at Firestone Point in Southern Barrens.", progress = "Ah, do you bring news from up north?", completion = "Is this from Crawgol? Wonderful! Despite all the turmoil in the world, we can't turn our back on the silithid threat. It is important to have people like Crawgol studying our enemy closely and learning its secrets for the fight ahead!\n\n<Tauna opens the book and glances over the first page. Her face falls.>\n\nOh. Well. I suppose it's something, at least.", sourceObjectiveStatus = "unverified-source-field" }
quests[24671] = { id = 24671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cluster Cluck", description = "Ridiculous! The greatest goblin mind of all time reduced to food detail? I made the Micro Mechachicken just for this reason and they let it get away!\n\n<Hobart turns a deeper shade of green as his blood pressure rises.>\n\nDo I look like I should be rounding up escaped cluckers? No, my friend, not I! Bamm most definitely, though he's too lazy.\n\nYour station in life has recently taken a turn for the worse. You do it!\n\nTake these remote control fireworks and attach them to the cluckers.", sourceObjective = "Capture 10 Wild Cluckers by attaching remote control fireworks to them.", progress = "Not enough cluckers, {name}. We'll all starve.", completion = "Success! Was there ever any doubt?\n\nGreely, fire up the poultryizer!", sourceObjectiveStatus = "unverified-source-field" }
quests[24672] = { id = 24672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onwards and Upwards", description = "I will do as Darius asked and have our people move through the Blackwald.\n\nYou ought to catch up with King Greymane.  He and Krennan went into Tempest's Reach after Lord Godfrey confirmed survivors had made their dwelling there.\n\nFollow the road out of Stormglen into the mountains.  I asked Krennan to wait for you at the bridge before Tempest's Reach.", sourceObjective = "Find Krennan Aranas on the road to Tempest's Reach.", completion = "{name}!\n\nGenn... they've taken Genn... they've taken... our king!", sourceObjectiveStatus = "unverified-source-field" }
quests[24673] = { id = 24673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Stormglen", description = "It'll be a long time before our nation comes together again.  The old political divisions pale in comparison to what divides us now.\n\nYet if there was ever a time for us to come together and unite against a common enemy, it is now.  And it is you, {name}, who have proven able to bridge the gap between our people.\n\nReturn to Stormglen and tell them it is safe to go through the Blackwald on their way to Tempest's Reach.  We will take care of any Forsaken who follow them.", sourceObjective = "Speak to Gwen Armstead in Stormglen.", completion = "King Greymane gave me a brief rundown of the plan before he set off for the Blackwald.  Doesn't make it sound any less crazy.", sourceObjectiveStatus = "unverified-source-field" }
quests[24674] = { id = 24674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaves to No One", description = "I was one of the few that escaped, {name}.  When the Forsaken took over our town and our mine, they treated us with utmost cruelty.\n\nThose of us who were weak and could not endure hard labor were worked to death by the abomination known as Brothogg.\n\nMy wife was among his victims, {class}, and I swore that one day her death would be avenged.  I am too frail now, but you can deliver justice... for my wife... for Gilneas!", sourceObjective = "Slay Brothogg the Slavedriver inside Emberstone Mine.", progress = "Is it done?", completion = "I thank you, {name}.  Our people will no longer suffer under that monstrosity's yoke.", sourceObjectiveStatus = "unverified-source-field" }
quests[24675] = { id = 24675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Meal", description = "I'm not dumb, {name}.  I know what's ahead of us.\n\nOur people are going to go through those gates and fight against an enemy that is better trained, has more numbers and better weapons than us.\n\nEven if we succeed, it'll be at a great cost.  For most of us, today's meal will be the last.\n\nI cannot fight, but I sure can cook.  Bring me meat from the stags that roam this area and I will ensure that the last meal these folks get will be their best.", sourceObjective = "Obtain 10 Sides of Stag Meat.", progress = "Did you get what I needed, {name}?", completion = "I thank you, {name}.  Our men and women will have a last good meal before they set off for battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[24676] = { id = 24676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Push Them Out", description = "The people are free, but the town is still occupied by the Forsaken.  They're cut off from their main force, so if we're to drive them out, now's our chance.\n\nTheir leader, Executor Cornell, is known  for his unbound ruthlessness.  Also among them is Valnov the Mad, a so-called scientist who carries out inhuman experiments on villagers too old to work the mines.\n\nTake care of them all.", sourceObjective = "Slay 4 Forsaken Infantry, Executor Cornell and Valnov the Mad in Emberstone Village.", progress = "You're back, {name}.", completion = "We have the people of Emberstone on our side now thanks to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24677] = { id = 24677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flank the Forsaken", description = "I thank you, {name}.  We can't rest on our laurels, however.\n\nWe found out about a mining town, currently under Forsaken occupation.  We sent some of my men, along with Crowley's daughter to the nearby livery stables to begin operations there.  Liam should be joining them shortly.\n\nI'll stay here and organize the final push for Gilneas City.  Speak to Lord Hewell to secure a horse to get you there.", sourceObjective = "Speak to Lord Hewell to obtain a ride to the Livery Outpost and report to Lorna Crowley.", completion = "I am glad to have you here, {name}.  We're surrounded by Forsaken on all sides and can use all the help we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[24678] = { id = 24678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knee-Deep", description = "It's time to pack it in, {name}.  Most of our people have made it through -- it's your turn now.\n\nTake this torch, you're going to need it.  The tunnel is full of nasty, knee-biting critters of the worst kind.  Use it to keep them at bay.\n\nSpeak to Krennan on the other side.", sourceObjective = "Use the Half-Burnt Torch to get to the other side of the tunnel beneath Gilneas City.\n\nProvided item:", completion = "You're here, {name}.  Most everyone made it through, but now we're stuck here... surrounded by our own... dead!", sourceObjectiveStatus = "unverified-source-field" }
quests[24679] = { id = 24679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patriarch's Blessing", description = "You've done it, {name}.  Even in these times we must honor our dead.\n\nTake these offerings and place them at Aderic's tomb.\n\nLet's hope that's enough to placate the ghosts of our ancestors.", sourceObjective = "Place the Blessed Offerings at Aderic's Tomb.", progress = "Is it done, {name}?", completion = "It's done, {name}.  The dead return to their slumber.", sourceObjectiveStatus = "unverified-source-field" }
quests[24680] = { id = 24680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keel Harbor", description = "We might've lost our city, but at least it looks like the dead have forgiven us.\n\nMeet with the rest of the survivors in Keel Harbor.\n\nI'm sure there's plenty to do before we're in the clear.  Genn hasn't arrived yet, so I suppose Lord Crowley will be in charge there.", sourceObjective = "Speak to Lord Darius Crowley at Keel Harbor in Gilneas.", completion = "It's good to see you again, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24681] = { id = 24681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Have Allies, But So Do We", description = "The night elves made good on their promise.  They've brought ships and are ready to offer us sanctuary in their lands.\n\nUnfortunately, the Forsaken's allies have arrived as well.\n\nThe orcs are advancing upon us while the Horde gunship prevents the transport ships from taking our people to safety.\n\nThe druids are holding the enemy back, but won't last long.  Fortunately, the elven ships were carrying siege weapons.  Take one of the glaive throwers and meet the enemy head on.", sourceObjective = "Use the Night Elven Glaivethrower to slay 40 Orc Raiders, 8 Wolfmaw Outriders and 4 Orcish War Machines.", progress = "You're back!", completion = "It's almost over, {name}.  Only one obstacle remains between us and survival.", sourceObjectiveStatus = "unverified-source-field" }
quests[24682] = { id = 24682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pit of Saron", description = "Quickly, through the portal! I'll find you on the other side.", sourceObjective = "Meet Lady Sylvanas Windrunner inside the entrance to the Pit of Saron.", completion = "Incapable fools. I begin to wonder if any of these louts from the tournament will be of any use at all. Perhaps you'll prove me wrong.", sourceObjectiveStatus = "unverified-source-field" }
quests[24683] = { id = 24683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pit of Saron", description = "Quickly, through the portal! I'll meet you on the other side.", sourceObjective = "Meet Lady Jaina Proudmoore just inside the Pit of Saron.", completion = "I underestimated this Scourgelord, and it's my men that paid for it. When I think that my guilt over Arthas' betrayal cannot go any deeper, he proves me wrong yet again.\n\nWe have to press on. We cannot let their sacrifice be meaningless.", sourceObjectiveStatus = "unverified-source-field" }
quests[24684] = { id = 24684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Weezil in the Henhouse", description = "<Gann grasps you with a blood-caked hand.>\n\nMy wounds are great but I will not rest until the dwarves of Bael Modan pay for their crimes. <Wheeze> We smuggled a man inside their fortress during our last raid. A goblin saboteur: Weezil Slipshadow. \n\nCreate a disruption at the gates - kill who you can - then slip inside the fortress of Bael'dun to the south and find Weezil.\n\nThat stronghold <cough> can only be destroyed from within, and Weezil can't do it alone.", sourceObjective = "Head into the Bael'Dun Keep and kill 10 Bael'Dun Dwarves (Riflemen, Soldiers, and Officers.) Then find Weezil Slipshadow, who should be hiding within.", progress = "Quiet, you big plodding brute! Keep your voice down.\n\nIf they spot us talking, pretend I'm just ordinary cheese.", completion = "You do good work, {class}. That riot you caused at the fortress entrance has these dwarves running around with their heads cut off.", sourceObjectiveStatus = "unverified-source-field" }
quests[24685] = { id = 24685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dwarf Fortress", description = "I don't know if you noticed on your way in, but this whole fortress is erected around a giant cannon. If we can just find the ammunition magazine, we could blow this place sky-high as easy as kiss-my-hand!\n\nBut to figure it out I'm going to need the fortress schematics, and I haven't been able to steal them yet.\n\nLook for the plans on the lowest floor, right down these stairs.", sourceObjective = "Acquire the Bael'Dun Fortress Schematics.", progress = "Give me the plans, quickly! Our time grows short.\n\nMostly because I've been eating my disguise.", completion = "Let's see, let's see.\n\nIt looks like the artillery shells are prepped here, then loaded into the secure magazine...\n\n<Weezil rubs his hands together.>\n\n{name}, are you ready to blow some stuff up?", sourceObjectiveStatus = "unverified-source-field" }
quests[24686] = { id = 24686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carried on the Waves", description = "The Bloodpetals of Un'Goro have a fascinating life cycle.\n\nThese trees in front of us bear seeds that fall down into the river when they mature.  The river's current then takes the seed north of here, where the seed hatches - almost like an egg - and a newborn Bloodpetal emerges.\n\nI require these seeds for my studies.  Take this net, and use it to scoop up the bright orange seeds in the river.  You'll have to hunt them down under the water.", sourceObjective = "Use Garl's Net to obtain 4 Bloodpetal Seeds.", progress = "Have you obtained the seeds yet?", completion = "Hmm... yes, these seeds will do nicely.  You have the gratitude of the Cenarion Circle, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24687] = { id = 24687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bouquets of Death", description = "You're already familiar with the first phase of the Bloodpetals' life cycle: the waterborne seed.  The next phase, however, is not so docile: the pack of juveniles.\n\nWhen Bloodpetals hatch, they quickly form gangs and travel together, offsetting their weakness with overwhelming numbers.  These packs of young lashers normally keep to themselves, but upset one of them and you upset them all.\n\nFor our safety and the safety of others, dispose of them.  They roam close by, to the west and north.", sourceObjective = "Kill 6 packs of Juvenile Lashers.", completion = "You return victorious.  Good, good... perhaps the crater will now be a bit safer to those who travel through it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24688] = { id = 24688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen'Aliri", description = "You've already met one of my new students, the young worgen named Garl.  My other student is a troll by the name of Zen'Aliri.  He currently camps with the explorers of Marshal's Expedition, to the west of here.\n\nTake these results to him, {name}, and tell him to read them well.", sourceObjective = "Report to Zen'Aliri in Marshal's Stand.", sourceObjectiveStatus = "unverified-source-field" }
quests[24689] = { id = 24689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flowing to the North", description = "Ithis Moonwarden is the night elf druid who indoctrinated me into the Cenarion Circle.  He has set up camp north of here, near the cliffs of the crater's easternmost edge.  Follow the flow of the Bloodpetal seeds, and I'll wager you'll find him nearby.\n\nMy studies are limited only to seeds and other reagents, but he pursues more advanced matters.  If you are curious to learn more about Un'Goro's flora, you should speak with him now.", sourceObjective = "Report to Ithis Moonwarden in the Roiling Gardens.", completion = "Ahh... did Garl send you?  How are his studies coming?  I find that he can be a bit slow at times, but he's truly a force to be reckoned with when he takes the form of the bear.\n\nNow, we have more pressing matters to attend to.", sourceObjectiveStatus = "unverified-source-field" }
quests[24690] = { id = 24690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blazerunner", description = "I'm still a bit concerned about these fire elementals, {name}.  One last request: head to the top of Fire Plume Ridge, and kill the one they call Blazerunner.  He's the biggest and strongest of all the fire elementals in the crater.  With him gone, I'll be able to sleep much better.", sourceObjective = "Kill Blazerunner.", completion = "At last, Blazerunner is dispatched.  Thanks, {name}... he was driving me batty.", sourceObjectiveStatus = "unverified-source-field" }
quests[24691] = { id = 24691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peculiar Delicacies", description = "Hey <bub/sweetie>, interested in making an extra dime?\n\nI've got it on good authority that some interested parties are paying BIG money for silithid legs.  Yes, you heard me right, silithid legs!  Apparently these things are delicious if you cook them right.  They're like underground lobsters, and they live just south of here.\n\nThing is, I'll need a good amount of them to pay for my overhead.  Think you could get me 8 dozen or so?", sourceObjective = "Obtain 96 Silithid Legs.", progress = "I need a lot of them because I've got to pay for shipping, handling, marketing... oh, and I've got to pay you as well.", completion = "Brilliant!  We're on the cusp of something big here, {name}.  Here's your share of the inevitably huge profits.\n\nNow, on to other matters...", sourceObjectiveStatus = "unverified-source-field" }
quests[24692] = { id = 24692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fledgling Colossus", description = "If you're here to help, then maybe you can help us with a lurking threat.\n\nTo the south lies the Slithering Scar, a quivering silithid outpost in the middle of the jungle.  You can't miss it.\n\nOne of my scouts reports that the silithid are harboring a young colossus in their large central underground chamber, and once it is fully grown, they plan to unleash it upon Un'Goro!\n\nThis must not be allowed to pass, {name}.  Find the colossus and kill it.", sourceObjective = "Kill the Gorishi Fledgling Colossus.", completion = "You've completed a remarkable task, {name}.  You are truly worthy of commendation.  Thank you, and congratulations!", sourceObjectiveStatus = "unverified-source-field" }
quests[24693] = { id = 24693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mossy Pile", description = "Here in Marshal's Stand, I can't really do too much profiteering without arousing suspicion from the scientists.  There is, however, another place where I might have use of you.\n\nMy business associate, Gremix, has a camp northwest of here, on the opposite side of the volcano.  He's a savvy business mind, and has a better eye for profit than even I do.  I'm sure he could put you to work, if you'd like to make some more coin.", sourceObjective = "Report to Gremix at Mossy Pile.", completion = "Very well, if Quixxil recommended you, then I suppose you're alright.  In all our years working together, Quixxil's never steered me wrong.", sourceObjectiveStatus = "unverified-source-field" }
quests[24694] = { id = 24694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shaper's Terrace", description = "<As you look into the orb in front of you, you hear a voice.>\n\nThe crystal pylons have been activated.  A sufficient number of crystals have been gathered.  The prerequisites have been met.  We are prepared for teleport to The Shaper's Terrace.\n\nSpeak to me when you are ready, {race}.  We will consult with The Watcher.", sourceObjective = "Speak with the Un'Goro Examinant to teleport to The Shaper's Terrace, then speak with Nablya.", completion = "I have been watching you, {name}.  Your arrival was not unforeseen.\n\nIn fact, your arrival here has been predetermined for some time now.", sourceObjectiveStatus = "unverified-source-field" }
quests[24695] = { id = 24695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ever Watching From Above", description = "When my master Khaz'Goroth shaped the world you call Azeroth, he designed Un'Goro Crater to be an area for experimentation.  You might call it the Titans' petri dish.\n\nIf you seek further knowledge about the methods in which we observe the world, pull the four levers behind me and complete my tests.", sourceObjective = "Pull the levers behind Nablya and complete her tests.", progress = "You have not yet completed my gauntlet, {name}.", completion = "You have proven to be both wise and agile, young {name}.  You have my blessing to take your newfound knowledge and spread it as you continue on your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[24697] = { id = 24697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Make Meat Fresh Again", description = "I don't believe we've met... I'm Nolen Tacker, Marshal Expeditions' new chief of the guards.  I'm also their chef.  There's actually more overlap than you'd think.\n\nI've got a fun little task for you.  Have you seen the spike pits around the perimeter of the camp?  See if you can convince some of the nearby dinosaurs to walk into them.  If you throw this rotten meat at them when they're not looking, it'll either make them hungry or angry.  Either way is fine, as long as they follow you into the pit!", sourceObjective = "Use the Scraps of Rotting Meat on nearby dinosaurs to lure them into the pits around Marshal's Stand.", progress = "Throw the meat, then let the dinosaurs chase you into the pit.  Easy as that!", completion = "Excellent work, {name}.  Now we're a bit safer from dinosaur attacks... plus I've got all this fresh meat to serve to my men.", sourceObjectiveStatus = "unverified-source-field" }
quests[24698] = { id = 24698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventures in Archaeology", description = "Hey, you want to try my new diemetradon dogs?  No?  Raptor risotto?  Pterrordax ptacos?\n\nFine.  Oh, I just remembered!  I have a friend nearby that might be able to use your assistance.  His name is Spark Nilminer, and he's Marshal Expeditions' chief archaeology officer.\n\nHe's been sent out to Golakka Hot Springs, to the west.  You'll likely find him on the springs' western shore.", sourceObjective = "Report to Spark Nilminer at Golakka Hot Springs.", completion = "Good ol' Nolen.  How is he doing?  Hopefully better than I am...", sourceObjectiveStatus = "unverified-source-field" }
quests[24699] = { id = 24699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormashh the Glutinous", description = "Hey, I know!  We've been looking at the wrong tar creatures.\n\nGremix once told me about a larger-than-normal tar creature that he ran into.  It lurks around the tar pit far to the east of here, south of Fungal Rock.  I'll bet that the bigger these creatures get, the stickier they get!  We'll make some money yet, {name}!\n\nDon't forget the scraper!", sourceObjective = "Kill Gormashh and obtain the Unbelievably Sticky Tar.", progress = "I'm counting on you, {name}.  I'm invested pretty heavily into this \"tar as glue\" scheme, and it'd be a shame if you came back empty-handed.", completion = "Yes, this tar is just the stuff...\n\nHey, wait a minute, my hands... I can't seem to get them apart...\n\nMaybe this wasn't such a good idea. Oh, but wait! Super sticky tar remover! That's where the real money is!", sourceObjectiveStatus = "unverified-source-field" }
quests[24700] = { id = 24700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard to Harvest", description = "The Lakkari Tar Pits, just north of here, conceal a hidden treasure: rare flowers that grow at the bottom of the pits.  These tarblossoms, as they're called, are valued for their beauty and their durability.  It's been a while since I last harvested tarblossoms, so there should be some new plants growing at the bottom of the pits.  Grab some for me?\n\nBy the way, good luck swimming in tar.  It's nothing like swimming in water.", sourceObjective = "Obtain 4 Tarblossom Blossoms.", progress = "Have you obtained the tarblossoms yet?  I don't see them...", completion = "Oh, there they are.  Great work, handsome!  Here's some gold.  You've earned it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24701] = { id = 24701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marshal's Refuse", description = "A big part of making money is shamelessness.  You have to be willing to profit off of the misfortune of others.  It all ends up boiling down to one question: How much do you love money?\n\nWhen Marshal and his crew abandoned their refuge up to the north, they left behind lots of supplies.  This stuff isn't rare, or even particularly valuable, but it's there if you're willing to take it.  His camp is up in the cliffs, to the north.\n\nOh, and be on the lookout for whatever it was that made them leave...", sourceObjective = "Obtain 10 Discarded Supplies.", progress = "Did you find anything good?", completion = "It's a bunch of junk, but it's a bunch of FREE junk, and that's all that matters to me.\n\nWell, mostly free.  Here's your share.  Thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[24702] = { id = 24702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Here Lies Dadanga", description = "Sturdy mount and trusted friend.\n\nDied shortly after the Cataclysm.  He always hated loud noises.\n\nIn lieu of flowers, please drop off a few Bloodpetal sprouts.  In life, he loved nothing more.", sourceObjective = "Obtain 10 Bloodpetal Sprouts.", progress = "Sturdy mount and trusted friend.\n\nDied shortly after the Cataclysm.  He always hated loud noises.\n\nIn lieu of flowers, please drop off a few Bloodpetal sprouts.  In life, he loved nothing more.", completion = "<You almost sense an air of gratitude as you place the Bloodpetal sprouts on the grave.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24703] = { id = 24703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Important Lesson", description = "What ho, traveler!  You must know that you set foot upon the camp of Maximillian of Northshire!  Mayhap you have heard tales sung of my many exploits?  I can see from the look in your eye that you have.  That glint of recognition plays upon your visage like the White Lady's reflection o'er Stonecairne Lake.\n\nIt is clear to me that you seek adventure.  As you seem able enough, and thoroughly well-intentioned, I would offer to make you my squire.", sourceObjective = "Speak to Maximillian of Northshire to learn more about becoming a squire.", progress = "Your first quest is a simple one, yet it somehow remains unfinished.  Endure my words and become my squire.", completion = "You please me, {name}.  From this day forward, you are no longer a simple beggar, but a squire loyal to Maximillian of Northshire.  Prepare yourself for our first sally, good squire, for together we shall plunge our fists elbow-deep into what they call adventure!", sourceObjectiveStatus = "unverified-source-field" }
quests[24704] = { id = 24704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Evil Dragons of Un'Goro Crater", description = "This crater is filled with a malignant breed of dragon.  Have you seen them?  They wander all about, parading their spiky backs and lizardy faces all around the Crater.\n\nDon't let them fool you, squire, for these dragons are no minions of graceful Alexstrasza.  They are clearly vicious, and direly in need of a hero's blade.\n\nI have decided that I will slay no less than 15 of them.  As my squire, you must come along.  Should we become separated, you may meet me back here at the Hot Springs.", sourceObjective = "Help Maximillian of Northshire slay 15 \"Dragons\".", completion = "...and that makes 15 of them.\n\nJustice had a name today... and that name was Maximillian of Northshire.  For Doloria!", sourceObjectiveStatus = "unverified-source-field" }
quests[24705] = { id = 24705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Town Dwellers Were Made to be Saved", description = "I've a feeling that we may find more than dragons here in this crater.  My paladin's instinct tells me that there are townsfolk nearby that require our aid. Those in distress cannot be ignored.\n\nLet us sally forth, Squire {name}!  The people of Un'Goro require our aid!", sourceObjective = "Rescue the Dweller by the Shore, the Dweller in the Cliffs, and the Dweller of the North.", completion = "Our duty is fulfilled.  Even so, it troubles me that the people of today are less than gracious...   Perhaps tomorrow we shall experience proper thankfulness.\n\nNow we must ride.  More adventures await!", sourceObjectiveStatus = "unverified-source-field" }
quests[24706] = { id = 24706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirits of Golakka Hot Springs", description = "A moment of seriousness now, {name}.  We have an important quest ahead of us.  The treacherous dragons that plague this valley will not cease their mischief until we destroy their repugnant brood mother.  Before we even attempt to complete such a task, we must ask the Light for aid.\n\nI have seen the Light manifest itself nearby, in the form of Spirits floating by the shores of Golakka Hot Springs.  Come, I must speak with them, and ask them for aid.", sourceObjective = "Stand by as Maximillian of Northshire speaks to 2 Steam Furies.", progress = "We have not completed our prayers.  Shall I join you?", completion = "Might I ask you a question?  What act have you committed to make the spirits so angry at you?  I'm impressed that you had the patience to sit so still while they pummeled you so violently.\n\nNow we may proceed.  The teeth and scales of Un'Goro's greatest dragon await us.", sourceObjectiveStatus = "unverified-source-field" }
quests[24707] = { id = 24707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ballad of Maximillian", description = "The time we have waited for is upon us, Squire {name}.  Un'Goro's brood mother will perish at my hands.  The gravity of our task weighs heavily on me, but with the power of the Light behind us, we are guaranteed to succeed.\n\nAre you ready to depart?", sourceObjective = "Help Maximillian of Northshire kill the Devilsaur Queen. If you become separated from Maximillian, meet him at Golakka Hot Springs in Un'Goro Crater.", completion = "The day is saved!  Huzzah!  Today we learned that while armor can be replaced, valor has no price.\n\nBecause of your key involvement in this task, I hereby graduate you from squire to fledgling knight.  No longer do the chains of servitude bind you to me; you are free to serve other masters.\n\nGo with honor, young hero!  For chivalry, the Light, and the beauty of Doloria!", sourceObjectiveStatus = "unverified-source-field" }
quests[24708] = { id = 24708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fossil-Finder 3000", description = "One of the things I hate the most about digging is the fact that half the time, all you find is dirt.  That's why I've been spending most of my time out here tinkering instead of digging.\n\nLet me show you what I've invented: the Fossil-Finder 3000.  I just put the finishing touches on it.  If it works properly, it should find the largest fossils in the area.  I know, sweet, huh?\n\nTest it out and see if you can find some ridiculously big dinosaur bones.", sourceObjective = "Obtain an Enormous Dinosaur Talon.", progress = "Have you found anything?  Did it work?", completion = "What an interesting femur you've brought here, but why's it all sharp and curvy?\n\n...\n\nWait a minute, that thing's a TALON?  A dinosaur with a talon that size would've been... well, really big, that's for sure.  Is this the only fossil that you found there?", sourceObjectiveStatus = "unverified-source-field" }
quests[24709] = { id = 24709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tale of Two Shovels", description = "Hey wait a minute, this bone has pickax marks on it.  These aren't yours, are they?  No, I recognize this mark... this must be that blasted dwarf!  Gah!\n\nLet me step back for a minute and explain.  There's another archaeologist south of here named Durrin Direshovel.  He practices a reckless, devil-may-care brand of archaeology that offends even me.\n\nA priceless fossil, ruined by sloppy pick-work.  This is the last straw, Durrin!\n\n{name}, go put an end to Direshovel and his negligent excavation.", sourceObjective = "Kill Durrin Direshovel and obtain Durrin's Archaeological Findings.", progress = "Is the deed done?  Did you manage to salvage his notes?", completion = "I knew it!  Durrin HAS been digging around here.  And he's been excavating what could be the archaeological find of the century!  Now I just have to find out where he's stashing the bones...\n\nThanks {name}.  You've been a great help.", sourceObjectiveStatus = "unverified-source-field" }
quests[24710] = { id = 24710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliverance from the Pit", description = "We need to make our way up the main path and through the cave to Tyrannus' rise.\n\nHe will be forced to confront us there lest we make our way into the citadel proper.\n\nGo now, {class}. My men and I will be there to stand by you when the confrontation with Tyrannus comes.", sourceObjective = "Kill Scourgelord Tyrannus.", completion = "Such a senseless waste! Arthas goes too far! I can only hope what we find in the Halls of Reflection makes this somehow worth it.\n\nIf what that vile gnome said is to be trusted, Frostmourne should be there, and with it, answers to confronting Arthas.", sourceObjectiveStatus = "unverified-source-field" }
quests[24711] = { id = 24711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmourne", description = "We must press on, hero. We've come so far... we're so close to our goal.\n\nI must delay a moment to send Elandra back to the airship. I'm uncertain how we're going to escape with so many men lost and so few to keep our path in secure.\n\nContinue on. I will meet you in the Halls of Reflection.", sourceObjective = "Meet Lady Jaina Proudmoore at the entrance to the Halls of Reflection.", completion = "The Halls of Reflection. Finally.\n\nLet me know when you are ready. Arthas may not be here, but it would be naive to think that he would leave Frostmourne unguarded entirely.", sourceObjectiveStatus = "unverified-source-field" }
quests[24712] = { id = 24712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliverance from the Pit", description = "We need to make our way up the main path and through the cave to Tyrannus' rise.\n\nThere, he will be forced to confront us there lest we make our way into the citadel proper.\n\nGo now, {class}. My men and I will be there to stand by you when the confrontation with Tyrannus comes.", sourceObjective = "Kill Scourgelord Tyrannus.", completion = "The Halls of Reflection lie ahead. If what that vile gnome said is to be trusted, Frostmourne should be there, and with it, answers to confronting Arthas.", sourceObjectiveStatus = "unverified-source-field" }
quests[24713] = { id = 24713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmourne", description = "Keep moving, the sword is close.\n\nI need a moment to send one of my dark rangers back to the airship. With all of our fodder gone, I will not be caught unprepared - we will need any help they can send.\n\nGo. I will meet you in the Halls of Reflection.", sourceObjective = "Meet Lady Sylvanas Windrunner inside the entrance to the Halls of Reflection.", completion = "The Halls of Reflection. Finally.\n\nLet me know when you are ready, {class}. I will not be so naive as to think that Arthas left his precious sword entirely unguarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[24714] = { id = 24714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing A-Me 01", description = "Unfortunately, something's happened to one of my greatest inventions.  You've seen mechanical squirrels, yes?  Well, to get closer to the apes of Un'Goro Crater, I created a mechanical ape to blend in with their kind--I call her A-Me 01.\n\nShe has been studying the local wildlife at Fungal Rock for several months, but she should have returned by now.  I fear the worst for her.\n\nCan you help me find her?", sourceObjective = "Find A-Me 01 at Fungal Rock.", completion = "A-Me lies motionless before you.  No power seems to be running through her components.", sourceObjectiveStatus = "unverified-source-field" }
quests[24715] = { id = 24715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repairing A-Me 01", description = "<Suddenly, the robotic gorilla's eyes light up, and it begins to speak.>\n\n\"...operational capacity... less than 5%... accidentally... punctured oil reservoir...\"\n\n\"...use coconut milk... rock... save A-Me 01...\"\n\n<A-Me closes her eyes.>", sourceObjective = "You're pretty sure that A-Me 01 has asked you to obtain an Un'Goro Coconut, crack it on the rock nearby, and give her the High Viscosity Coconut Milk.", progress = "<A-Me 01 has gone into power save mode.>", completion = "You pour the coconut milk into what appears to be A-Me 01's oil reservoir.  You hear the sound of gears whirring and actuators firing.", sourceObjectiveStatus = "unverified-source-field" }
quests[24717] = { id = 24717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Apes of Un'Goro", description = "There's plenty of money to be had here in Un'Goro, you just need to know where to look!\n\nApes may be common here in Un'Goro, but they're much rarer up north.  In Everlook, a gorilla hide fetches ten times what you'll get for it down here!\n\nI'm not going to send you all the way up to Winterspring - that'd be irresponsible - but I could use your help actually obtaining some hides.\n\nYou'll find gorillas at Fungal Rock, to the northeast, near a waterfall.  Don't forget to check inside the cave!", sourceObjective = "Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Gremix at Mossy Pile.", progress = "I never know what style is in vogue, so I'll want a few different colors.  Try to get hides from each different type of gorilla there.", completion = "Wow, 2 of each color!  You're certainly an overachiever, {name}.  My companions and I could use a {race} like you around here.  Ever consider a career in profiteering?", sourceObjectiveStatus = "unverified-source-field" }
quests[24718] = { id = 24718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mighty U'cha", description = "Looking around, you see bits of red fur laying around this part of the cave.  It appears to match the consistency of gorilla fur.\n\nBased on your conversations with Gremix, you know that he would almost certainly be interested in a red gorilla hide, if you were to obtain one.", sourceObjective = "Bring U'cha's Pelt to Gremix at Mossy Pile.", progress = "Red fur?  What're you waiting for!  Go back and get that red gorilla!  I'll pay you double!", completion = "Wow, look at this one!  Not just the color, but the size of it... you could cover a tauren with this.\n\nHere you go, {name}.  You've earned this.  Stick around, I'm sure we can find something else for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[24719] = { id = 24719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claws of White", description = "Stop, {race}.  I could use the help of a {class} like you.\n\nRight outside this camp, there are raptors with deadly claws.  I've been using the claws for druid rituals, but it doesn't seem to be working.  However, I did notice that some of those raptors sometimes have white claws, when most have deathly black ones.\n\nThe earth works in strange ways.  Maybe you could fetch me some of the white claws, and I'll try one last time?", sourceObjective = "Obtain 5 White Ravasaur Claws.", progress = "Have you gotten any of the claws yet?", completion = "My mentor says that sometimes you have to take away from nature before you can give back.  These raptors... I feel that they died for good cause.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24720] = { id = 24720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystals of Power", description = "I'm sure you've noticed 'em, {name}. They're everywhere!\n\nWhat am I talking about? Why, the crystals, of course!\n\nThe crystals... They're all over the crater. Most people ignore them, but I have a strange feeling that they hold power within them.\n\nSay, I'm running a little low on the crystals I have here -- think you might be able to collect some more for me?  \n\nYou'll find yellow crystals to the northwest, red crystals to the... oh, I'm sure you'll figure it out.", sourceObjective = "Collect 7 Power Crystals of each color: red, blue, yellow, and green.", progress = "I just know I'm onto something here, {name}!", completion = "Now I will continue my experiments! Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24721] = { id = 24721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eastern Pylon", description = "High up in the cliffs above me there is a large crystal pylon.  Who placed it there, I cannot say, nor can I determine any reason that it would be built in such a strange place.\n\nMaybe you can make more of it than I can.  I personally don't care what it does, so you needn't report back to me, but perhaps one of the scholars in Marshal's Stand might be interested in what you discover.", sourceObjective = "Touch the Eastern Crystal Pylon in Un'Goro Crater.", completion = "You were right to bring this pylon to my attention, {name}.  This is just the sort of thing I've been studying.", sourceObjectiveStatus = "unverified-source-field" }
quests[24722] = { id = 24722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Northern Pylon", description = "You've done us a number of favors, {name}... now let Gremix do one for you.  The attacks on Marshal's Refuge were terrible, undoubtedly.  They came without warning, and took no prisoners.  They were lucky that so many of them survived.\n\nA few weeks ago, I came across a crystal pylon in the cliffs to the northeast of here, east of Marshal's Refuge.  I think the pylon and the attacks may be related somehow.  Maybe you can investigate?  I'm sure someone in Marshal's Stand will thank you.", sourceObjective = "Discover the location of the Northern Crystal Pylon in Un'Goro Crater.", progress = "Yes, {name}?", completion = "You think this may be related to the attacks on Marshal's Refuge, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24723] = { id = 24723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Western Pylon", description = "Durrin's research touched on one area that intrigues me: a potential link between the titans and the dinosaurs.  J.D. Collie back at camp is always talking about titan this and crystal that... maybe she'd be interested.\n\nBefore you report to her, you might want to check out the crystal pylon not far from here.  It's just up in the cliffs, to the west of here.  It's got crystals on it, and it always seemed to me like it might have something to do with the titans.", sourceObjective = "Discover the location of the Western Crystal Pylon.", completion = "A pylon in the west?  And a relationship between titans and dinosaurs?  This is a lot to take in, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24724] = { id = 24724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Restore" }
quests[24725] = { id = 24725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Charge" }
quests[24726] = { id = 24726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Force" }
quests[24727] = { id = 24727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Spire" }
quests[24728] = { id = 24728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Ward", progress = "The Pylon table allows you to combine green power crystals with red power crystals.\n\nAccording to J.D.'s manual, this combination can be used to strengthen the protection you have against physical damage.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[24729] = { id = 24729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Yield" }
quests[24730] = { id = 24730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roll the Bones", description = "You'd think that being chief digger for Marshal Expeditions means I like digging.  There might be worse things to do in this world... but none really leap to mind.\n\nWe were supposed to be digging in Terror Run - FANTASTIC name by the way - for dead stegodons and diemetradons.  Well, there are plenty of live ones there too!  Wil and Hol are still all about studying this death trap, so we need those dinosaur bones.  Between you and me though, bringing some from live ones will work out just as well.", sourceObjective = "Obtain 8 Dinosaur Bones.", progress = "Think whatever you want of me, but they're not going to care if the bones they get to research are from ancient stegodons and diemetradons or the ones that almost devoured us wholesale when we were trying to set up our camps.  I'll just be happy if we get out of here alive...", completion = "Excellent, these should do the trick.  And now, if you'll permit me, in case anyone's listening...\n\nTHANKS FOR DIGGING ALL OF THESE BONES OUT OF THE GROUND FOR US AND NOT HURTING THE NATIVE BEASTS IN ANY WAY.\n\nWhether you really did or didn't, I don't want to know.  Let's keep it that way, shall we?  Here - maybe this will keep your lips shut on the whole thing.  Anything to get out of here alive, I say!", sourceObjectiveStatus = "unverified-source-field" }
quests[24731] = { id = 24731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fare of Lar'korwi", description = "Once, a long time ago, a brother of mine took some meat from one of Lar'korwi's kills. He didn't know it at the time, but Lar'korwi saw him from the forest. Lar'korwi followed my brother for days, destroying everything he touched. My brother, scared, finally decided to run from the Crater and leave Lar'korwi behind.\n\nLar'korwi killed him not far from this spot.\n\nIf you want to provoke Lar'korwi, find a fresh kill of his and take some of the meat from it.\n\nStart your search to the west.", sourceObjective = "Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass.", progress = "Do not take my words lightly, {name}. If you truly wish to face this creature, then you must be careful... and smart. It will take a great deal of strength and insight to draw out Lar'korwi and defeat him.", completion = "This will do nicely, {name}. It seems Lar'korwi eats well these days. Although, I wonder where he found a threshadon in this area. Odd.\n\nRegardless, I will hold onto this until you are ready for your confrontation with the beast. Do not worry for my safety--I am sure you've angered Lar'korwi enough that he will not kill me until after he's tasted your flesh.", sourceObjectiveStatus = "unverified-source-field" }
quests[24732] = { id = 24732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scent of Lar'korwi", description = "I'm actually surprised he has not come for you yet, {name}. But all is well, for I have a final plan that will bring the monster to us.\n\nBeing the dominant male gives Lar'korwi rights to breed with any female he chooses--and he chooses many of them. You'll find many ravasaur eggs to the west of here. Get close to them and you should provoke an attack by his mates. The females produce an awful smell from a gland in their heads that allow males to know they are ready to breed. Bring me two of those glands.", sourceObjective = "Obtain 2 Ravasaur Pheromone Glands.", progress = "Be careful, {name}. Getting close to any nest of eggs surely will provoke the mothers... even if you've already secured a gland from one. The mothers can be just as deadly as Lar'korwi himself when they fight to protect their young. But, if you are successful, then we shall have a definitive way of bringing Lar'korwi out from hiding.", completion = "Ah, fine specimens, {name}. The two pieces you've found should be perfect for baiting Lar'korwi into the open. I cannot wait to see the outcome of your fight with the monster. He is a massive thing with claws as sharp as the finest blades. You will look into his eyes and you will know death.", sourceObjectiveStatus = "unverified-source-field" }
quests[24733] = { id = 24733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bait for Lar'korwi", description = "This will be the most difficult part because there is some complexity to the plan.  Continue following the river to the north, and look for a bend in the river.  It was here I saw Lar'korwi last.  You will know you are in the right area because of all the bones from massive creatures that once wandered nearby.\n\nTake the meat you recovered and place it there.  Then, rub this mixture I created on the meat.\n\nIf both lures mingled together do not bring Lar'korwi to you, then I know nothing else that will.", sourceObjective = "Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.", progress = "Do not let fear overpower you, {name}. Fear is the great betrayer... you must remain strong!", completion = "The Earth Mother be praised! You've done it! Fair play to you, {name}. You have proven to be a great hunter in your own right. Your spirit is strong. Your bravery unmatched. And your strength has been fortified. I bow down to your skills.\n\nOnly the greatest of my ancestors could have accomplished something so incredible. Congratulations.", sourceObjectiveStatus = "unverified-source-field" }
quests[24734] = { id = 24734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost!", description = "You've got to help me, {name}! My friend, Ringo left earlier to explore the volcano to the north of here, and he has been gone way too long. I am really worried about him.\n\nDo you think you could find him? Why don't you take my canteen with you -- if you do find Ringo, I'm sure he'll need it!", sourceObjective = "Find signs of Ringo at Fire Plume Ridge.", progress = "Ringo's sack rests on the rock in front of you.", completion = "You find what appears to be Ringo's belongings.  If he left these here, he can't have gone far away.  Maybe you should look for him.", sourceObjectiveStatus = "unverified-source-field" }
quests[24735] = { id = 24735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Help From My Friends", description = "Ugh... It's so hot...\n\nI was exploring this area, when all of a sudden, the heat just became unbearable. I must be suffering from heat exhaustion.\n\nPlease, help me get back to my friend Spraggle at Marshal's Stand. I think I'm well enough to follow you there.\n\nI am feeling a little out of it, so you can slap me if I'm feeling woozy.  If I do happen to faint again, just splash some water on me from Spraggle's canteen. That should work, I hope...", sourceObjective = "Lead Ringo to Spraggle Frock at Marshal's Stand.\n\nIf Ringo feels weak, slap him. If he faints, use Spraggle's Canteen to revive him.", progress = "I've been so worried about Ringo...", completion = "Ringo's not in the best shape, {name}, but I am glad to have him back in one piece!\n\nThank you for finding him.", sourceObjectiveStatus = "unverified-source-field" }
quests[24736] = { id = 24736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shizzle's Flyer", description = "I'm making a flying machine!\n\nI got stranded here, and I'm absolutely horrible at finding my way around. I'd take a gryphon or wind rider back to Gadgetzan, but those beasts just scare me to death.\n\nSo, will you help me? All I have left to build is the wings, and I was thinking that the webby scales from the pterrordax in the Screaming Reaches to the west would be perfect. There's no way I'm going to go up against one of those, but you look pretty tough. Why don't you give it a try?", sourceObjective = "Collect 35 Webbed Pterrordax Scales.", progress = "Every great vehicle needs a name... I was thinking I'd call it... Pwned!", completion = "Yes, these scales are perfect. I should be able to get this flyer off the ground with these scales for sure!\n\nThanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[24737] = { id = 24737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Sticky", description = "I'm always looking for a quick way to earn a gold, {name}. If you help me with my newest idea, I'll let you in on a little of the profit. How does that sound to you?\n\nI thought so!\n\nWe're going to be making some glue. Head to the tar pits just north of here, and collect me some tar. Not just any tar, now, you'll need to get it from the beasts that live around the tar pits. As a bonus, if you use my tar scraper on their corpses, you'll keep your hands nice and clean.", sourceObjective = "Collect 8 samples of Super Sticky Tar.", progress = "Tara's done it again -- this super sticky glue will be all the rage!", completion = "Yeah, this tar is pretty sticky, I guess.  I mean, it's sticky, but it's not \"make fistfuls of money\" sticky.  I guess I'll have to keep thinking.", sourceObjectiveStatus = "unverified-source-field" }
quests[24740] = { id = 24740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volcanic Activity", description = "Welcome.  I'm Williden Marshal, and my sister and I run this expedition of explorers and scientists.  You have a moment?\n\nI don't like the look of those elementals on that volcano, {class}.  We have too much equipment, too many notes... one crazed elemental could streak its way through our camp and do terrible, terrible damage.\n\nShow them that their new neighbors aren't to be trifled with.  And bring back the ash that they leave behind... we might as well do a little science while we're at it.", sourceObjective = "Collect 9 samples of Un'Goro Ash from the fire elementals around the volcano in Un'Goro Crater.", progress = "Do you think the volcano is active?  I wonder why it didn't explode when the cataclysm hit.", completion = "I hope that did the trick.  I'll take the ash... this may come in handy sometime down the line.", sourceObjectiveStatus = "unverified-source-field" }
quests[24741] = { id = 24741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trading Up", description = "Hobart thinks he's going to feed us on those tiny clucker eggs? Bah! We're going to get some real eggs!\n\nI've already set up some traps on the Raptor Rise up the path to the east. Take this bunch of wild clucker eggs and lay them in the traps. The spiny raptors will go right after the clucker eggs, and then you'll get to trade up to their larger eggs.\n\nGenius!", sourceObjective = "Gather 5 Spiny Raptor Eggs.", progress = "How many did you get? I can just taste the massive omelet we're going to cook up now!", completion = "Nice! Look at the size of those things!\n\nThere's no way that Grapplehammer's going to be able to top those!", sourceObjectiveStatus = "unverified-source-field" }
quests[24742] = { id = 24742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding the Source", description = "I created a thermometer to take readings of the temperatures at the volcano, and I'd like to find the hottest lava flows.  It gives the measurements in degrees Kraklenheit!\n\nHere, take it, and take readings of the temperatures at the ridge whenever you see a hot spot!\n\nHot spots usually take the form of a glowing, rocky pillar jutting out of the ground.  You'll find them around the base of Fire Plume Ridge... one trip around the perimeter will likely suffice.", sourceObjective = "Krakle in Un'Goro Crater wants you to find the hottest area of Fire Plume Ridge.\n\nWhenever you find a hot spot, use the thermometer to check the temperature. Keep looking until you find the hottest one.", progress = "I'd go there myself, but... I'm a little scared of the fire elementals there!", completion = "These results are astounding!  My boss will be pleased.  Thank you, kind {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[24743] = { id = 24743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow's Edge", sourceObjective = "Listen well, {class}. In accepting this weapon your fate is sealed.\n\nOvercome or succumb.\n\nI have placed your feet upon this path. You are therefore my personal responsibility. Should you falter, I am duty-bound to deliver you from this life.\n\nRemember my words, {race}, and do not fail.", sourceObjectiveStatus = "unverified-source-field" }
quests[24744] = { id = 24744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Biggest Egg Ever", description = "Bamm Megabomb? Who does he think he is? His spiny raptor eggs are no match for what we are about to recover!\n\nAs you well know, each Town-In-A-Box is equipped with a micro mechachicken for just such a dietary emergency. Luckily for us, my keen intellect was able to deduce the location that our prodigious, pre-programmed poultry ran off to.\n\nHead north to the Scorched Gully. But beware, its circuit boards are fried and I imagine it's not so micro any longer!", sourceObjective = "Recover the Biggest Egg Ever.", progress = "Just think about the accolades that will rain down upon me... us, when the Biggest Egg Ever is returned!", completion = "Eureka! My genius saves the day yet again! Take that Bamm Megabomb!\n\nAnd now, to reap the benefits!", sourceObjectiveStatus = "unverified-source-field" }
quests[24745] = { id = 24745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something is in the Air (and it Ain't Love)", description = "The inside of the card is scribbled with mad, detailed plans to infect most of Azeroth.  You should show this to one of Steamwheedle's investigators immediately!", sourceObjective = "Bring the Faded Lovely Greeting Card to Inspector Snip Snagglebolt in Stormwind.", progress = "Did you take care of those no-good scheming villains?", completion = "What've you got there?\n\nOh hey, this is big. Real big. Most of the crazy details in one little package. Thanks - you really helped us reel this all in. Good working with ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24746] = { id = 24746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[24747] = { id = 24747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage!", description = "These dwarven artillery shells have a built-in airburst timer. This is easy! Just sabotage one of the artillery shells in the loading bay and then hoist it up into the magazine. Boom, baby. BOOM!\n\nYou'll find the shells in one of two loading bays behind the main garage on this level. It's right around the corner.\n\nOnce you've rigged the artillery shell... Run! Run like the wind, {name}! Then report to Gann back at camp. I'll be right behind you.", sourceObjective = "Sabotage a Dwarven Artillery Shell and then flee from Bael'Dun before it explodes.", completion = "Bael'dun? Destroyed?\n\n<Wincing in pain, Gann twists his head to peer behind him, where plumes of smoke darken the skyline.>\n\n{name}, my friend. You have avenged Taurajo and avenged the Tauren people. The invaders will not soon recover from that blow. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24748] = { id = 24748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lich King's Last Stand", description = "Shadowmourne; a newly forged weapon already steeped in this world's history, reborn into an unrivaled destiny.\n\nWith this weapon you bear a solemn responsibility, and the time to carry out that charge is at hand.\n\nTake this weapon of myth and legend and march on the enemy. Avenge the countless heroes lost in his merciless campaign. Bring rest to their tortured souls.\n\nSteel yourself, {class}, and guide Shadowmourne to fulfill the purpose of its creation.", sourceObjective = "Highlord Darion Mograine in Icecrown Citadel wants you to kill the Lich King.", completion = "So, at last it is done.\n\nMay the people of Azeroth remember our deeds here forevermore. May the sacrifices of so many burn in their hearts eternally. May they never fail to risk mortal peril in the face of great evil.", sourceObjectiveStatus = "unverified-source-field" }
quests[24749] = { id = 24749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unholy Infusion", description = "Before your weapon can reach its full potential it must be endowed with its signature powers. First among them is unholiness.\n\nYou must seek out and defeat the one called Professor Putricide, but his death is not your only goal. You must use his resources against him.\n\nFind a way to absorb his mutated slime. Use the foul substance to infuse your weapon with the power of the unholy. Only when this has been done shall I reveal your next task.", sourceObjective = "Highlord Darion Mograine wants you to infuse Shadow's Edge with Unholy power and slay Professor Putricide.\n\nThis quest may only be completed in 25 person difficulty of Icecrown Citadel.", completion = "Well done, {class}.\n\nThe completion of our work draws near.", sourceObjectiveStatus = "unverified-source-field" }
quests[24750] = { id = 24750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Soratha to the east.", sourceObjective = "Meet with Soratha in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually have an intense look about ya though. Fiery eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", sourceObjectiveStatus = "unverified-source-field" }
quests[24751] = { id = 24751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the arcane arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", sourceObjective = "Destroy 6 Tiki Targets.", completion = "Not bad, mon. Ya have a natural flow to ya spells - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", sourceObjectiveStatus = "unverified-source-field" }
quests[24752] = { id = 24752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Mage", description = "I tink I have something I can show ya. It's pretty simple really, but it should help.\n\nWhen ya arcane energies line up perfectly, ya can release a volley of arcane missiles dat wil be devastatin' ya enemeis. It may take some time and some luck for ya to get a chance at practicin' these magics, so be patient.\n\nTry it out. Let me know when ya tink you have it down.", sourceObjective = "Speak to Soratha to train Arcane Missiles. Practice using Arcane Missiles 2 times against a Tiki Target.", completion = "Good work, mon! Dis stuff come easy to ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24753] = { id = 24753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", sourceObjective = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", sourceObjectiveStatus = "unverified-source-field" }
quests[24754] = { id = 24754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", sourceObjective = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day.", sourceObjectiveStatus = "unverified-source-field" }
quests[24755] = { id = 24755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", sourceObjective = "Report to Vol'jin at Darkspear Hold.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear.", sourceObjectiveStatus = "unverified-source-field" }
quests[24756] = { id = 24756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Infusion", description = "Your weapon is ready to be endowed with the power of blood.\n\nYou must face Queen Lana'thel in battle and subject yourself to her Blood Mirror. This will cause Shadow's Edge to drink the blood of the nearest living being. That being would be you, {race}.\n\nOnce the blade has been thus awakened, allow the Queen's Frenzied Bloodthirst to take hold of you, feed the blade thrice to sate it, and then give the queen an ignominious death.\n\nMay her screams pierce the ears of the Lich King as he awaits his fate.", sourceObjective = "Highlord Darion Mograine wants you to infuse Shadow's Edge with blood and defeat Queen Lana'thel.\n\nThis quest may only be completed in 25 person difficulty of Icecrown Citadel.", completion = "Well done, {class}.\n\nShadowmourne is nearly within reach.", sourceObjectiveStatus = "unverified-source-field" }
quests[24757] = { id = 24757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Infusion", description = "Shadow's Edge is prepared to receive its final infusion of power.\n\nSindragosa, the enemy's own mount, must fall. But before she is brought down, you must sustain four of her frozen breath attacks without tasting death.\n\nWithout his dragon, nothing shall stand between you and the Lich King.", sourceObjective = "Highlord Darion Mograine has instructed you to slay Sindragosa after subjecting yourself to 4 of her breath attacks while wielding Shadow's Edge.\n\nThis quest may only be completed in 25 person difficulty of Icecrown Citadel.", completion = "The axe has drunk its fill, {race}, and the forge is nearly ready for the creation of Shadowmourne...", sourceObjectiveStatus = "unverified-source-field" }
quests[24758] = { id = 24758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Nekali to the east.", sourceObjective = "Meet with Nekali in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually have a weathered look about ya though. Wise eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", sourceObjectiveStatus = "unverified-source-field" }
quests[24759] = { id = 24759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the natural arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", sourceObjective = "Destroy 6 Tiki Targets.", completion = "Not bad, mon. Ya have a natural flow to ya spells - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", sourceObjectiveStatus = "unverified-source-field" }
quests[24760] = { id = 24760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Shaman", description = "I tink I have something I can show ya. It's pretty simple really, but it should help.\n\nFocusin' tha power of da elements into yer weapon can allow ya to unleash a quick, vicious attack on your enemies. Dis should be easy enough for ya to make a lot of use of it.\n\nTry it out. Let me know when ya tink you have it down.", sourceObjective = "Speak to Nekali to train Primal Strike. Use Primal Strike 3 times against a Tiki Target.", progress = "Der are many other ways to enchant yer weapon. Ya'll learn more wit time.", completion = "Good work, mon! Dis stuff come easy to ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24761] = { id = 24761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", sourceObjective = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", sourceObjectiveStatus = "unverified-source-field" }
quests[24762] = { id = 24762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", sourceObjective = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day.", sourceObjectiveStatus = "unverified-source-field" }
quests[24763] = { id = 24763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", sourceObjective = "Report to Vol'jin at Darkspear Hold.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear.", sourceObjectiveStatus = "unverified-source-field" }
quests[24764] = { id = 24764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Zen'Tabra to the east.", sourceObjective = "Meet with Zen'Tabra in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually have a wild look about ya though. Fierce eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", sourceObjectiveStatus = "unverified-source-field" }
quests[24765] = { id = 24765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the druidic arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", sourceObjective = "Destroy 6 Tiki Targets.", progress = "Strength isn't da end all of defeating ya enemy, and it most certainly isn't tha end all of stayin' alive. Fightin' is about balance. This'll become more apparent as ya learn animal forms, but it holds true even now. Everytin' has its time and place.", completion = "Not bad, mon. Ya have a natural flow to ya casts - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", sourceObjectiveStatus = "unverified-source-field" }
quests[24766] = { id = 24766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Druid", description = "I tink I have something I can show ya. It's pretty simple really, but it should help.\n\nBy calling on nature, we can mend bones and cuts. We can bring back even da most gravely wounded ally ta fight on.\n\nTry it out. Let me know when ya tink you have it down.", sourceObjective = "Speak to Zen'Tabra to train Rejuvenation. Practice using Rejuvenation on a Wounded Darkspear Watcher in the Darkspear Training Grounds.", progress = "Veteran druids can take on animal forms, grantin' great speed, tough skin, or even tha ability ta fly.", completion = "Good work, mon! Dis stuff come easy to ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24767] = { id = 24767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", sourceObjective = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", sourceObjectiveStatus = "unverified-source-field" }
quests[24768] = { id = 24768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", sourceObjective = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day.", sourceObjectiveStatus = "unverified-source-field" }
quests[24769] = { id = 24769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", sourceObjective = "Report to Vol'jin at Darkspear Hold.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear.", sourceObjectiveStatus = "unverified-source-field" }
quests[24770] = { id = 24770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Legati to the east.", sourceObjective = "Meet with Legati in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually have a sly look about ya though. Fierce eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", sourceObjectiveStatus = "unverified-source-field" }
quests[24771] = { id = 24771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start with da basics. I need ta know dat you know how ta swing dose weapons you're totin' around.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", sourceObjective = "Destroy 6 Tiki Targets.", completion = "Not bad, mon. Ya have a natural flow to ya swings - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", sourceObjectiveStatus = "unverified-source-field" }
quests[24772] = { id = 24772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Rogue", description = "I tink I have something I can show ya. It's pretty simple really, but it should help.\n\nAs ya fight ya enemies, ya will be able to see dere weaknesses and set up for devastating combo attacks. After ya've struck a few blows to weaken ya foe, finish dem off with a vicious evisceration attack.\n\nTry it out. Let me know when ya tink you have it down.", sourceObjective = "Speak to Legati to train Eviscerate. Use Eviscerate 3 times against a Tiki Target.", completion = "Good work, mon! Dis stuff come easy to ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24773] = { id = 24773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", sourceObjective = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", sourceObjectiveStatus = "unverified-source-field" }
