quests[24828] = { id = 24828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Destruction", progress = "You seek to continue down the path of destruction?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[24829] = { id = 24829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Destruction", progress = "You seek to continue down the path of destruction?", completion = "You are a true champion of our cause, {name}.  None can claim to be more dedicated to the struggle than you.\n\nThe enemy speaks of your name only in whispers, for they know you're a force to be reckoned with.\n\nAccept this humble gift as a reward for your many triumphs." }
quests[24830] = { id = 24830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Wisdom", progress = "You seek to continue down the path of wisdom?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[24831] = { id = 24831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Wisdom", progress = "You seek to continue down the path of wisdom?", completion = "You are a true champion of our cause, {name}.  None can claim to be more dedicated to the struggle than you.\n\nYou are a bastion of wisdom and our allies speak of you with the greatest reverence.  Many of them owe you their own lives.\n\nAccept this humble gift as a reward for your many triumphs." }
quests[24832] = { id = 24832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Vengeance", progress = "You seek to continue down the path of vengeance?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[24833] = { id = 24833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Vengeance", progress = "You seek to continue down the path of vengeance?", completion = "You are a true champion of our cause, {name}.  None can claim to be more dedicated to the struggle than you.\n\nIt is rumored that the minions of the Scourge fear you more than they do the Lich King himself.  You are vengeance incarnate.\n\nAccept this humble gift as a reward for your many triumphs." }
quests[24834] = { id = 24834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Courage", progress = "You seek to continue down the path of courage?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[24835] = { id = 24835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Courage", progress = "You seek to continue down the path of courage?", completion = "You are a true champion of our cause, {name}.  None can claim to be more dedicated to the struggle than you.\n\nYou are a source of inspiration to our allies and your unshakeable valor gives pause to even the most seasoned of our enemy's generals.\n\nAccept this humble gift as a reward for your many triumphs." }
quests[24836] = { id = 24836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Heart", progress = "You seek to change the path you walk, {name}?", completion = "May you find what you're looking for, brother." }
