quests[24848] = { id = 24848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fireworks At The Gilded Rose", description = "Kid, this is about more than just perfume. There were some rockets in that crate, and they had some kind of chemical payload inside. I can't analyze it here, but I'll spare ya the trip to the lab.\n\nNah, you gotta find the guy who made these. I know the maker's mark. Snivel Rustrocket.\n\nI got a tip from a reliable source that Snivel's here in Stormwind, livin' it up at the Gilded Rose. What's more, he had some dame on his arm. Marion Sutton was the name. Go to the Gilded Rose and see what she knows.", sourceObjective = "Speak to Marion Sutton at the Gilded Rose in Stormwind's Trade District.", completion = "You... You're not Snivel. Did he send you? He's so late, I had started to give up hope...\n\n<Tears start welling up in the woman's eyes once she realizes that you aren't there to deliver a message from Snivel.>\n\nThat's not like my Snivel, but what other choice is there?", sourceObjectiveStatus = "unverified-source-field" }
quests[24849] = { id = 24849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot On The Trail", description = "I'd better start from the beginning. It was love at first sight, {name}. There was just something about that goblin from the moment I set eyes on him.\n\nAfter a wonderful week together, Snivel said he had come into a lot of money and that he was going to take me on a long vacation to the South Seas! Can you believe it?\n\nAnyway, he told me to pack while he ran some errands to the bank, the auction house, and the barber shop, but he never came back! I'm beginning to think he's nothing but a big liar!", sourceObjective = "Look for Snivel Rustrocket in the Stormwind Counting House, the Auction House, and the Barbershop in Stormwind City.", progress = "Did you find him?", completion = "All he talked about was leaving town with all his money? Then he really has abandoned me, hasn't he?\n\nOh, {name}, I was such a fool to fall for him, but how could I help myself? He was so irresistible!", sourceObjectiveStatus = "unverified-source-field" }
quests[24850] = { id = 24850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snivel's Sweetheart", description = "Kid, this is about more than just perfume. There were some rockets in that crate, and they had some kind of chemical payload inside. I can't analyze it here, but I'll spare ya the trip to the lab.\n\nNah, you gotta find the guy who made these. I know the maker's mark. Snivel Rustrocket.\n\nI hear Snivel's livin' it up here in Orgrimmar. What's more, he's got himself a girlfriend -- some orc dame named Roka. She's supposed to meet him at Gotri's Traveling Gear in the Drag before they make their escape.", sourceObjective = "Speak to Roka at Gotri's Traveling Gear in Orgrimmar's Drag district.", completion = "You're not Snivel. He was supposed to be here an hour ago! What have you done with him?\n\n<Roka seems to calm down when you tell her that you're looking for Snivel, too. Then, tears start to well up in her eyes.>\n\nThis isn't like my sweet Snivel. Do you think something's happened to him?", sourceObjectiveStatus = "unverified-source-field" }
quests[24851] = { id = 24851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot On The Trail", description = "I'd better start from the beginning. It was love at first sight, {name}. There was just something about that goblin from the moment I set eyes on him.\n\nAfter a wonderful week together, Snivel said he had come into a lot of money and that he was going to take me on a long vacation to the South Seas! Can you believe it?\n\nAnyway, he told me to pack while he ran some errands to the bank, the auction house, and the barber shop, but he never came back! I'm beginning to think he's nothing but a big liar!", sourceObjective = "Look for Snivel Rustrocket in the Orgrimmar Bank in the Valley of Strength, the Auction House, and the Barbershop in Orgrimmar.", progress = "Did you find him?", completion = "All he talked about was leaving town with all his money? Then he really has abandoned me, hasn't he?\n\nI can't believe I fell for such a horrible goblin! But he was so irresistible when we first met.", sourceObjectiveStatus = "unverified-source-field" }
quests[24852] = { id = 24852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Tribe, Imprisoned", description = "Despite their size, the Bristleback greatly outnumber us. A pack ambush can easily overwhelm even the largest tauren.\n\nMany new initiates have taken up arms to defend our home. Some have given their lives, but others have been captured alive.\n\nPlease, find their cages and free them. The battle should keep the quilboar distracted.", sourceObjective = "Open 4 Quilboar Cages.", completion = "Thanks to you, our people are free to fight for our home.", sourceObjectiveStatus = "unverified-source-field" }
quests[24854] = { id = 24854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Stormclaw", description = "Zen'Aliri been studyin' the ways of the druid, {race}.  Hopefully one day, Zen'Aliri join the Druids of the Talon, and soar over this crater as a storm crow.\n\nBut for now, my mentor says I stay here and wait.  So Zen'Aliri waits.\n\nI know another druid who might be able to use your help.  His name is Garl Stormclaw, and he's somewhere to the east of here, studying reagents.  Maybe you go talk to him?", sourceObjective = "Report to Garl Stormclaw at the entrance to Un'Goro Crater.", completion = "Zen'Aliri was wise to send you here.  I've hit a dead end in my studies.", sourceObjectiveStatus = "unverified-source-field" }
quests[24855] = { id = 24855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aberrant Flora", description = "Look how strangely the plant life reacts to the bloodpetals in the Roiling Gardens to the north.  The trees are enveloped with more flowers and vines than usual.  Large, sporous blossoms project themselves from the ground where they once did not.\n\nThe land is speaking to us, {race}.  The bloodpetals are destroying the balance.\n\nAs my final task, I ask you to visit the swarming adult bloodpetals and prune their numbers.", sourceObjective = "Kill 11 Bloodpetals. Any type of adult Bloodpetal will do.", completion = "The scent of bloodpetal pollen hangs about your head, {class}.  This is good.\n\nYou've earned your reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[24856] = { id = 24856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion Imminent!", description = "Your work here is done for now, but there's no rest for the wicked, eh?\n\nYou remember Megs Dreadshredder, our old marketing rep? She's taken some others over the hills to the southeast, just past the Raptor Rise. If you follow the path east out of town and follow it south at the fork, you can't miss her.\n\nApparently there's some trouble or other brewing with the snake-men at the ruins on the shore. Go see if you can't sort it all out, would you?", sourceObjective = "Speak with Megs Dreadshredder at the western entrance to the Ruins of Vashj'elan on the Lost Isles.", completion = "Boss, we gotta problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[24857] = { id = 24857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Camp Narache", description = "After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache.\n\nSurely Chief Hawkwind could use this information!", sourceObjective = "Bring the Bristleback Attack Plans to Chief Hawkwind in Camp Narache.", progress = "You have a look of concern about you, {name}. What news do you bring?", completion = "This is quite alarming indeed! But with this information we can call on our brethren from Bloodhoof Village to help thwart the attack. You have saved the lives of many {race}, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24858] = { id = 24858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bilgewater Cartel Represent", description = "Looks like the naga down there in the ruins are preparing to invade our Town-In-A-Box. I have lots of dead scouts here as proof.\n\nI don't know about you, but I'm not about to let them try. Let's get the jump on them!\n\nCould you lay the foundation for our new coastal holdings by replacing their banners with our own? That's some prime real estate down there!", sourceObjective = "Destroy 10 Naga Banners, replacing them with Bilgewater Cartel Banners.", completion = "I wish I could have seen the looks on their scaly faces when you blew up their banners and replaced them with our own.\n\nOn second thought, I don't want to be close enough to see their snarls.", sourceObjectiveStatus = "unverified-source-field" }
quests[24859] = { id = 24859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga Hide", description = "It's oft whispered in dark corners of a material so fine, so exquisite to the touch, that goblins of sophisticated taste will spend any amount of moolah to get their hands on some.\n\nOf course, I'm speaking of naga hide!\n\n<Brett looks around to make sure no one else is listening in.>\n\nI know that you're going to head down there and that it's inevitable that you're going to have to fight those snakes. Hey, they're not going to have a use for their hides anyway. They'll be dead!", sourceObjective = "Collect 5 Intact Naga Hides.", progress = "Well? How many do you have for me? I think that a 95 to 5 split is more than generous.", completion = "We're going to be filthy rich, I tell you! Well, if we can get off of this island, that is.", sourceObjectiveStatus = "unverified-source-field" }
quests[24861] = { id = 24861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Rites, First Rites", description = "The camp is safe, and the quilboar driven off, all thanks to you, young one. You have my personal thanks for what you have done for my mother, my son, and for all of us.\n\nIt is now time to put Greatmother Hawkwind to rest. Lay the final offering at her feet, {name}, and we will say our goodbyes.", sourceObjective = "Use the Ceremonial Offering at Greatmother Hawkwind's grave.", progress = "Do not be shy, {name}. I am honored to have you lay the final offering.", completion = "There is balance in all things. As Greatmother Hawkwind's spirit takes its final journey, you will begin your first.", sourceObjectiveStatus = "unverified-source-field" }
quests[24862] = { id = 24862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Running the Gauntlet", description = "Look around you, {class}. We've had no luck dislodging the Horde from the hidden trails that overlook this valley. They appear out of nowhere to ambush our supply caravans and then disappear into the hills!\n\nI need you to run the gauntlet to Honor's Stand and let them know the roads still aren't safe. Talk to Mattingly, the supplies officer by the gate.\n\nAnd kill a few of these brutes along the way!", sourceObjective = "Kill 8 Hunter Hill Scouts.", completion = "They're ambushing the roads to Stonetalon, too? We just can't get a break here. Where are they coming from, anyways?", sourceObjectiveStatus = "unverified-source-field" }
quests[24863] = { id = 24863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Siege", description = "Horde scouts hiding in the ruins up ahead ambushed my supply train. Only two of my bodyguards made it out of there alive. And me? I used to have hair!\n\nThe supplies I was delivering are scattered through the ruins up ahead. Gather them up and take them to Janice Mattingly at Honor's Stand. If they can't make it to Stonetalon, at least we can keep them out of Horde hands...", sourceObjective = "Gather 10 Stonetalon Supply crates from the ruins west of Honor's Stand.", progress = "What's the story out there?", completion = "What ... our supplies? These were meant for Stonetalon.\n\nNo matter, at the rate we're going, we need them more here. Honor's Stand has been cut off from the coast, {name}. Commander Singleton is at his wit's end.", sourceObjectiveStatus = "unverified-source-field" }
quests[24864] = { id = 24864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irresistible Pool Pony", description = "I've got a plan and you're the only one that I know crazy enough to pull it off!\n\nI need you to take this irresistible pool pony to the Vashj'elan Spawning Pool and inflate it. Then, swim down to their hatchlings with it on. I'll bet anything that the hatchlings can be lured away to follow you.\n\nBring them back here and we'll proceed with the next phase of the plan.", sourceObjective = "Use the Irresistible Pool Pony to lure 12 Naga Hatchlings.", progress = "That's not enough hatchlings.", completion = "Oh, they're so cute! I wish that we could turn them into little plush toys and sell them for a gazillion macaroons!", sourceObjectiveStatus = "unverified-source-field" }
quests[24865] = { id = 24865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is This Stuff Still Good?", description = "You find what appears to be a crate of food, left behind when this camp was abandoned.  On the outside of the crate, you can make out a stamp that says \"PROPERTY OF MARSHAL EXPEDITIONS\".\n\nPerhaps you might find someone who could use this?", sourceObjective = "Return the Crate of Foodstuffs to Williden Marshal at Marshal's Stand.", progress = "What have you got there?", completion = "Oh... wow... it's some really old food.  Hey Hol'anyee, take a look at this!  This {race} brought us those old rations that we abandoned!\n\nNo, not from Marshal's Refuge... from the old base camp!\n\n\n\nI'm not sure I want to peek inside.  I'll just give it to Nolen, I guess... he'll know what to do with it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24866] = { id = 24866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Abandoned Research Camp", description = "You find what appears to be a piece of research equipment, left behind when this camp was abandoned.  Chiseled onto the side of the device are the words \"PROPERTY OF MARSHAL EXPADISHUNS\".\n\nPerhaps you might find someone who could use this?", sourceObjective = "Return the Research Equipment to Hol'anyee Marshal at Marshal's Stand.", progress = "Yes, {name}?", completion = "Well I'll be... that's Shizzle's old portable dinomometer!  Where did you find this?\n\nI'm surprised it's still functional, even after all these years.  I'll have it delivered to Shizzle promptly.", sourceObjectiveStatus = "unverified-source-field" }
quests[24868] = { id = 24868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surrender or Else!", description = "{name}, you and Ace need to march those naga hatchlings down there and use them as leverage to convince the leader of the naga to surrender to us.\n\nAce knows where to go on the south side of the ruins... just follow him.", sourceObjective = "Deal with the leader of the Naga at the Ruins of Vashj'elan.", progress = "What's wrong?", completion = "A faceless of the deep? What's that? That does NOT sound like a naga!\n\nWell, you killed it, whatever it was. It doesn't matter now. We have other fish to fry....", sourceObjectiveStatus = "unverified-source-field" }
quests[24869] = { id = 24869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deprogramming", description = "We had hoped to place a man on the inside of the Cult of the Damned, to give us an inside angle on the Lich King's machinations, but we... underestimated the persuasive powers of Arthas and his dark minister, Lady Deathwhisper.\n\nOur man, Darnavan, is one of them now.\n\nIf you plan on fighting your way through the Oratory ahead, please keep your eyes peeled for Darnavan. If you can bring him back to us alive, we can attempt to reverse the Cult's brainwashing.", sourceObjective = "Defeat Lady Deathwhisper while ensuring that Darnavan survives.", progress = "Darnavan has been among the Cult for so long now that there is no telling how he will react. He is a well-trained warrior, so be on your guard!", completion = "Thank you, {name}!\n\nI owe you a debt of gratitude for rescuing a friend whom I had thought forever lost to the clutches of the Cult. And the Argent Crusade owes you a debt for the invaluable intelligence Darnavan brings with him from his time walking the halls of this Citadel as one of the Cult.\n\nPlease, take this as a token of this appreciation, and may the Light bolster you as you carve a path through this terrible place.", sourceObjectiveStatus = "unverified-source-field" }
quests[24870] = { id = 24870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Ramparts", description = "As if this place weren't enough of a madhouse to begin with, we're fighting a war on two fronts up here, with the Scourge on one side and those blasted Alliance dogs on our other flank!\n\nWe are here to clear a safe landing for our vessels, but a behemoth of a giant on the other side of the Ramparts is hurling debris at anything that comes close and keeping our smaller ships at bay.\n\nI'll be honest -- he's a bit much for us to handle, but you and your companions look up to the task.", sourceObjective = "Slay the Rotting Frost Giant.", progress = "Is the giant dead?", completion = "The giant is dead? For the Horde!\n\nThe way onward will soon be clear. Take some of these spoils of the battle as a token of our gratitude, and we will drink together in celebration once the Frozen Throne has been ground to dust!", sourceObjectiveStatus = "unverified-source-field" }
quests[24871] = { id = 24871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Ramparts", description = "As if this place weren't enough of a madhouse to begin with, we're fighting a war on two fronts up here, with the Scourge on one side and those blasted Horde dogs on our other flank!\n\nWe are here to clear a safe landing for our vessels, but a behemoth of a giant on the other side of the Ramparts is hurling debris at anything that comes close and keeping our smaller ships at bay.\n\nI'll be honest -- he's a bit much for us to handle, but you and your companions look up to the task.", sourceObjective = "Slay the Rotting Frost Giant.", progress = "Is the giant dead?", completion = "The giant is dead? Praise the Light!\n\nThe way onward and upward is clear. Take some of these spoils of the battle as a token of our gratitude, and we will drink together in celebration once the Frozen Throne has been ground to dust!", sourceObjectiveStatus = "unverified-source-field" }
